COLLDATA("khalqafaalur","ur",[[257,"سیدنا ابو موسیٰ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے ان سے فرمایا: ’’ابو موسیٰ! تمہیں آل داؤد کے مزامیر میں سے کچھ مِزْمَار (خوبصورت آواز) دیے گئے ہیں۔‘‘","",{"k":"صحیح البخاري (5048)۔ صحیح مسلم (793)"}],[258,"سیدنا براء بن عازب رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے ابو موسیٰ رضی اللہ عنہ کو قراءت کرتے ہوئے سنا تو فرمایا: ’’یہ تو گویا آل داؤد کی آوازیں ہیں۔‘‘","",{"k":"مسند الرویاني (356)۔ مسند أبي یعلیٰ (1670، 1733)"}],[259,"ہانی بن یزید رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا: ’’مجھے کوئی ایسا عمل بتائیے جو مجھے جنت میں لے جائے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اچھی گفتگو کرنے اور کھانا کھلانے کو عادت بنا لو۔‘‘","",{"k":"الأدب المفرد للبخاري (811)۔ المستدرك للحاکم (1/23)۔ المعجم الکبیر للطبراني (470)"}],[260,"سیدنا عمرو بن حارث رضی اللہ عنہ کہتے ہیں کہ میں نے نبی کریم صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ’’جسے قرآن ترو تازہ پڑھنا پسند ہو، جیسے نازل ہوا ہے تو اسے چاہیے کہ ابن ام عبد (یعنی عبد اللہ بن مسعود رضی اللہ عنہ) جیسی قراءت کرے۔‘‘","",{"k":"مسند أحمد: 4/278 – 279۔ مصنف ابن أبي شیبۃ: 10/520۔ سند میں دینار نامی راوی مجہول ہے لیکن اس روایت کے شواہد موجود ہیں جن کا تذکرہ 561 نمبر پر موجود حدیث کی تخریج میں ہوگا۔"}],[261,"سیدنا فَضَالہ بن عُبید رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تعالیٰ خوش الحان شخص کا قرآن اس سے زیادہ توجہ سے سنتا ہے جتنا کہ گانا سننے والا اپنی توجہ گانے والی کی طرف مبذول کرتا ہے۔‘‘","",{"k":"سنن ابن ماجہ: 1/425، رقم: 1340۔ مسند أحمد: 6/20۔ صحیح ابن حبان: 3/31، رقم: 754۔ سند ضعیف ہے۔"}],[262,"سیدنا ابوموسیٰ رضی اللہ عنہ بیان کرتے ہیں نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’جب میرے اشعری احباب رات میں آتے ہیں تو میں ان کی تلاوتِ قرآن کی آواز پہچان جاتا ہوں۔ اگرچہ دن میں مَیں نے ان کی اقامت گاہوں کو نہ دیکھا ہو لیکن جب رات میں وہ قرآن پڑھتے ہیں تو ان کی آواز سے میں ان کی اقامت گاہوں کو پہچان لیتا ہوں۔ میرے انہی اشعری احباب میں ایک مرد دانا بھی ہے کہ جب کہیں اس کی سواروں سے مڈبھیڑ ہو جاتی ہے یا آپ نے فرمایا کہ دشمن سے ‘ تو ان سے کہتا ہے کہ میرے دوستوں نے کہا ہے کہ تم تھوڑی دیر کے لیے ان کا انتظار کر لو۔‘‘","",{"k":"صحیح البخاري (4232)۔ صحیح مسلم (2499)"}],[263,"سیدنا براء بن عازب رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’قرآن کو اپنی آوازوں سے مزین کرو۔‘‘","",{"k":"سنن أبي داود (1468)۔ سنن النسائي (2/179 – 180)۔ سنن ابن ماجہ (1342)"}],[264,"یہ روایت قتیبہ از جریر از اعمش از طلحہ کی سند سے بھی مروی ہے۔"],[265,"اسی طرح عثمان از جریر از منصور از طلحہ کی سند سے بھی منقول ہے۔"],[266,"اس کے علاوہ عثمان از جریر از اعمش کی سند بھی بیان کی گئی ہے۔"],[267,"سیدنا براء بن عازب رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’قرآن کو اپنی آوازوں کے ذریعہ زینت دو۔‘‘"],[268,"حدیث کے ایک راوی عبد الرحمن بن عَوْسَجہ کہتے ہیں کہ مجھے اس روایت کے الفاظ «زینوا القرآن بأصواتکم» بھول گئے تھے۔ پھر ضحاک بن مزاحم نے مجھے یاد دلایا۔","",{"k":"صحیح ابن خزیمۃ (1551)"}],[269,"سیدنا براء بن عازب رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’اپنی آوازوں کے ذریعہ قرآن کو مزین کرو۔‘‘ حدیث کے راوی عبد الرحمن کا بھی یہی قول ہے۔","",{"k":"مسند أبي داود الطیالسي (738)۔ السنن الکبری للبیھقي (2/53)"}],[270,"یہی الفاظ سہیل از ان کے والد از ابو ہریرہ رضی اللہ عنہ کی سند سے نبی کریم صلی اللہ علیہ وسلم سے مروی ہیں۔","",{"k":"فضائل القرآن لأبي عبید القاسم بن سلام (219)۔ صحیح ابن حبان (750)"}],[271,"براء بن عازب رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’قرآن کو اپنی آوازوں کے ذریعہ زینت دو۔‘‘","",{"k":"مسند أحمد (4/285)۔ المستدرك للحاکم (1/573)"}],[272,"امام بخاری رحمہ اللہ فرماتے ہیں: اس حوالہ سے زیادہ تر روایات اہل علم کے ہاں مشہور ہیں۔"],[273,"بلا شک وشبہ آل داؤد کے مزامیر اور آوازیں مخلوق تھیں، جیسا کہ اللہ عز وجل کا فرمان ہے:\n﴿ وَخَلَقَ كُلَّ شَيۡءٍ ﴾ [الفرقان: 2]\n’’اور اس نے ہر چیز کو پیدا کیا۔‘‘\nاور یہ بھی فرمایا:\n﴿ فَلَا تَجۡعَلُواْ لِلَّهِ أَندَادًا وَأَنتُمۡ تَعۡلَمُونَ ﴾ [البقرۃ: 22]\n’’پس اللہ کے لیے کسی قسم کے شریک نہ بناؤ، جب کہ تم جانتے ہو۔‘‘"],[274,"سیدنا براء بن عازب رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو نمازِ عشاء میں سورت التین کی تلاوت کرتے ہوئے سنا۔ آپ صلی اللہ علیہ وسلم جیسی اچھی آواز یا قراءت میں نے کسی کی نہیں سنی۔‘‘","",{"k":"صحیح البخاري (769، 7546)۔ صحیح مسلم (464)"}],[275,"نوفل بن اِیاس ہُذَلِی کہتے ہیں کہ ہم خلافت ِ فاروقی میں مسجد میں ٹولیوں کی صورت میں قیام اللیل کرتے تھے۔ ایک گروہ اِدھر کھڑا ہوتا اور ایک گروہ اُدھر کھڑا ہوتا۔ لوگوں کا زیادہ رجحان اس گروہ کی طرف ہوتا تھا جس کا قاری خوبصورت آواز والا ہوتا۔ یہ دیکھ کر عمر رضی اللہ عنہ نے فرمایا: ’’میرے خیال میں ان لوگوں نے قرآن کو گانا بنا لیا ہے۔ اللہ کی قسم! اگر میرے اندر استطاعت رہی تو میں اس طریقہ کار کو بدل دوں گا۔‘‘ چنانچہ تین راتوں کے بعد انہوں نے ابی (بن کعب) کو حکم دیا تو انہوں نے سب کو جماعت کروائی۔"],[276,"علقمہ کہتے ہیں کہ عبد اللہ بن مسعود رضی اللہ عنہ نے مجھے کہا: ’’پڑھو۔‘‘ علقمہ کی آواز بہت اچھی تھی۔ چنانچہ انہوں نے پڑھا، تو عبد اللہ بن مسعود رضی اللہ عنہ نے کہا: ’’تلاوت کرو۔ میرے والدین تم پر قربان ہوں۔‘‘","",{"k":"فضائل القرآن لأبي عبید: 1/326، رقم: 211۔ سنن سعید بن منصور: 1/225۔ مصنف ابن أبي شیبۃ: 10/524۔ سند صحیح ہے۔"}],[277,"امام بخاری رحمہ اللہ فرماتے ہیں: اللہ عزوجل کا فرمان ہے:\n﴿ وَإِذَا قُرِئَ ٱلۡقُرۡءَانُ فَٱسۡتَمِعُواْ لَهُۥ ﴾ [الأعراف: 204]\n’’اور جب قرآن پڑھا جائے تو اسے کان لگا کر سنو۔‘‘\nدوسری جگہ فرمایا:\n﴿ وَٱتۡلُ مَآ أُوحِيَ إِلَيۡكَ مِن كِتَابِ رَبِّكَۖ ﴾ [الکھف: 27]\n’’اے نبی! جو کچھ آپ کی طرف وحی کیا گیا ہے آپ کے اپنے پروردگار کی کتاب میں سے وہ انھیں پڑھ کر سنا دو۔‘‘\nمزید فرمایا:\n﴿ إِنَّ ٱلَّذِينَ يَتۡلُونَ كِتَٰبَ ٱللَّهِ ﴾ [فاطر: 29]\n’’بےشک جو لوگ اللہ کی کتاب پڑھتے ہیں۔‘‘\nمزید فرمایا:\n﴿ وَمَا كُنتَ تَتۡلُواْ مِن قَبۡلِهِۦ مِن كِتَٰبٍ وَلَا تَخُطُّهُۥ بِيَمِينِكَۖ ﴾ [العنکبوت: 48]\n’’اس سے پہلے تو آپ کوئی کتاب پڑھتے نہ تھے، نہ کسی کتاب کو اپنے ہاتھ سے لکھتے تھے۔‘‘\nمزید فرمایا:\n﴿ يَتۡلُونَهُۥ حَقَّ تِلَاوَتِهِۦٓ ﴾ [البقرۃ: 121]\n’’وہ اسے اس طرح پڑھتے ہیں جیسا کہ اسے پڑھنے کا حق ہے۔‘‘\nمزید فرمایا:\n﴿ وَٱذۡكُرۡنَ مَا يُتۡلَىٰ فِي بُيُوتِكُنَّ مِنۡ ءَايَٰتِ ٱللَّهِ وَٱلۡحِكۡمَةِۚ ﴾ [الأحزاب: 34]\n’’اور تمہارے گھروں میں اللہ کی جن آیات اور دانائی کی باتوں کی تلاوت کی جاتی ہے، انہیں یاد کرو۔‘‘\nمزید فرمایا:\n﴿ يَتۡلُونَ ءَايَٰتِ ٱللَّهِ ءَانَآءَ ٱلَّيۡلِ ﴾ [آل عمران: 113]\n’’جو رات کے اوقات میں اللہ کی آیات کی تلاوت کرتے ہیں۔‘‘\nمزید فرمایا:\n﴿ إِنَّ هَٰذَا ٱلۡقُرۡءَانَ يَهۡدِي لِلَّتِي هِيَ أَقۡوَمُ ﴾ [الإسراء: 9]\n’’حقیقت یہ ہے کہ یہ قرآن وہ راستہ دکھاتا ہے جو سب سے زیادہ سیدھا ہے۔‘‘"],[278,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’ان آیات سے واضح ہوگیا کہ تلاوت تو نبی کریم صلی اللہ علیہ وسلم اور صحابہ رضی اللہ عنہم کا فعل تھا اور وحی رب تعالیٰ کی طرف سے تھی۔‘‘"],[279,"سیدہ عائشہ رضی اللہ عنہا کا درج ذیل فرمان بھی اسی معنیٰ پر دلالت کرتا ہے: ’’میرے وہم وگمان میں بھی نہیں تھا کہ اللہ تعالیٰ میرے بارے میں ایسی وحی نازل فرمائیں گے جس کی تلاوت کی جاتی رہے گی۔‘‘ اس فرمان میں سیدہ عائشہ رضی اللہ عنہا نے واضح کردیا کہ وحی اللہ کی طرف سے ہوتی ہے اور لوگ اس کی تلاوت کرتے ہیں۔"],[280,"ابن شہاب نے بیان کیا، انہیں عروہ بن زبیر، سعید بن مسیب، علقمہ بن وقاص اور عبیداللہ بن عبداللہ بن عتبہ بن مسعود نے نبی کریم صلی اللہ علیہ وسلم کی زوجہ مطہرہ عائشہ رضی اللہ عنہا پر تہمت لگنے کا واقعہ بیان کیا۔ یعنی جس میں تہمت لگانے والوں نے ان کے متعلق افواہ اڑائی تھی اور پھر اللہ تعالیٰ نے ان کو اس سے بری قرار دیا تھا۔ ان تمام راویوں نے پوری حدیث کا ایک ایک ٹکڑا بیان کیا۔ اس میں سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں: ’’پھر میں اپنے بستر پر لیٹ گئی۔ مجھے پورا یقین تھا کہ میں بَری ہوں اور اللہ تعالیٰ میری براءت ضرور کرے گا لیکن اللہ کی قسم! مجھے اس کا وہم و گمان بھی نہیں تھا کہ اللہ تعالیٰ میرے بارے میں ایسی وحی نازل فرمائے گا جس کی تلاوت کی جائے گی۔ میں اپنی حیثیت اس سے بہت کم تر سمجھتی تھی کہ اللہ تعالیٰ میرے بارے میں (قرآن مجید کی آیت) نازل فرمائے جس کی تلاوت کی جاتی رہے گی۔ اللہ تعالیٰ نے اس موقع پر سورۃ النور کی دس آیات نازل فرمائیں، جن میں سے پہلی آیت یہ ہے:\n﴿ إِنَّ ٱلَّذِينَ جَآءُو بِٱلۡإِفۡكِ عُصۡبَةٌ مِّنكُمۡۚ ﴾ [النور: 11]\n’’یقین جانو کہ جو لوگ یہ جھوٹی تہمت گھڑ کر لائے ہیں وہ تمہارے اندر ہی کا ایک ٹولہ ہے۔‘‘","",{"k":"صحیح البخاري (4750)۔ و2593 و 2637 و 4141 و 4690 و 4749 و 5212۔ صحیح مسلم (2770)"}],[281,"عبد اللہ نے لیث سے اور انہوں نے یونس سے اسی طرح روایت کیا ہے۔","",{"k":"الرد علی الجھمیۃ للدارمي (311)"}],[282,"صالح، ابن اسحاق اور فُلَیح نے ابن شہاب سے اسی طرح بیان کیا ہے۔","",{"k":"صحیح البخاري (4141، 2661)۔ صحیح مسلم (2770)۔ السیرۃ النبویۃ لابن ھشام (3/297)"}],[283,"امام بخاری رحمہ اللہ فرماتے ہیں: فرمان باری تعالیٰ ہے:\n﴿ قُل لَّئِنِ ٱجۡتَمَعَتِ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَىٰٓ أَن يَأۡتُواْ بِمِثۡلِ هَٰذَا ٱلۡقُرۡءَانِ لَا يَأۡتُونَ بِمِثۡلِهِۦ وَلَوۡ كَانَ بَعۡضُهُمۡ لِبَعۡضٍ ظَهِيرًا ﴾ [الإسراء: 88]\n’’کہہ دو کہ: اگر تمام انسان اور جنات اس کام پر اکٹھے بھی ہوجائیں کہ اس قرآن جیسا کلام بنا کر لے آئیں، تب بھی وہ اس جیسا نہیں لاسکیں گے، چاہے وہ ایک دوسرے کی کتنی مدد کرلیں۔‘‘\nلیکن یہ قرآن کلام اللہ ہے جسے انسان اور فرشتے پڑھتے ہیں۔ اس کی وضاحت درج ذیل حدیث سے ہوتی ہے:"],[284,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب اللہ تعالیٰ کسی بندہ سے محبت کرتا ہے تو جبرائیل علیہ السلام کو آواز دیتا ہے کہ فلاں سے محبت کرو۔ چنانچہ جبرائیل علیہ السلام عرش کو اٹھانے والے فرشتوں میں اس کا چرچا کرتے ہیں، تو اہلِ عرش اس سے محبت کرتے ہیں۔ پھر ساتویں آسمان والے اہلِ عرش کا شور سنتے ہیں۔ پھر اس بندے کی محبت ساتویں آسمان تک پہنچ جاتی ہے۔ پھر ایک ایک کرکے تمام آسمانوں سے ہوتی ہوئی آسمانِ دنیا تک پہنچ جاتی ہے۔ یوں آسمانِ دنیا والے اس سے محبت کرنے لگتے ہیں۔ پھر اس کی محبت زمین پر اترتی ہے تو اہلِ زمین اس سے محبت کرنے لگتے ہیں۔ نفرت کا معاملہ بھی اسی طرح ہے۔‘‘","",{"k":"صحیح البخاري (7485)۔ صحیح مسلم (2637)"}],[285,"فرمان الٰہی ہے:\n﴿ فَإِنَّمَا يَسَّرۡنَٰهُ بِلِسَانِكَ ﴾ [مریم: 97]\n’’چنانچہ (اے پیغمبر) ہم نے اس قرآن کو تمہاری زبان میں آسان بنا دیا ہے۔‘‘\nاور فرمایا:\n﴿ وَلَقَدۡ يَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ ﴾ [القمر: 17]\n’’اور حقیقت یہ ہے کہ ہم نے قرآن کو نصیحت حاصل کرنے کے لیے آسان بنا دیا ہے۔‘‘"],[286,"نبی کریم صلی اللہ علیہ وسلم کا فرمان ہے: ’’ہر انسان کےلیے وہی کچھ آسان بنایا گیا ہے جس کےلیے اس کی تخلیق ہوئی ہے۔‘‘ یہ روایت آدم نے شعبہ سے، انہوں نے یزید رِشْک سے، انہوں نے مطرف سے اور انہوں نے عمران بن حصین رضی اللہ عنہ کے واسطہ سے نبی کریم صلی اللہ علیہ وسلم سے بیان کی ہے۔","",{"k":"صحیح البخاري (6596)۔ صحیح مسلم (2649)"}],[287,"عمران رضی اللہ عنہ بیان کرتے ہیں کہ میں نے عرض کی: ’’یا رسول اللہ! عمل کرنے والے کس وجہ سے عمل کریں؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’ہر ایک جس کام کےلیے تخلیق کیا گیا ہے، اسے اسی کی آسانی دی جاتی ہے۔‘‘","",{"k":"صحیح البخاري (7551)۔ صحیح مسلم (2649)"}],[288,"سلیمان از حماد از یزید از مطرف از عمران کی سند سے یہی الفاظ مروی ہیں۔","",{"k":"صحیح مسلم (2649)"}],[289,"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’ہر عمل کرنے والے کو اس کے عمل کی آسانی فراہم کی جاتی ہے۔‘‘","",{"k":"صحیح مسلم (2648)"}],[290,"سیدنا عبد اللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’ہر ایک کو اسی کی توفیق دی جاتی ہے جو اس کے مقدر میں ہوتا ہے۔‘‘"],[291,"سیدنا عبد اللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ عمر رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم سے(کچھ) کہا تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’ہر ایک کو آسانی فراہم کی جاتی ہے۔‘‘","",{"k":"سنن الترمذي (2135)۔ مسند أحمد (2/52، 77)۔ مسند أبي داود الطیالسي (11)"}],[292,"حجاج کہتے ہیں کہ ہمیں شعبہ نے یہی حدیث بیان کی۔"],[293,"سیدنا عمر بن خطاب رضی اللہ عنہ بیان کرتے ہیں کہ میں نے نبی کریم صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ’’ہر انسان کو اسی کی توفیق ملتی ہے جس کےلیے اسے پیدا کیا گیا ہوتا ہے۔‘‘"],[294,"شعبہ سے یہ روایت بیان کرنے میں غُندَر اور جُدِّی نے عبد اللہ کی متابعت کی ہے۔","",{"k":"مسند أحمد (1/29)۔ السنۃ لابن أبي عاصم (ص 163)"}],[295,"اللہ عز وجل کا فرمان ہے:\n﴿ وَٱخۡتِلَٰفُ أَلۡسِنَتِكُمۡ وَأَلۡوَٰنِكُمۡۚ ﴾ [الروم: 22]\n’’اور (اس کی نشانیوں میں سے) تمہاری زبانوں اور تمہارے رنگوں کا الگ الگ ہونا ہے۔‘‘"],[296,"امام بخاری رحمہ اللہ فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم نے واضح فرما دیا ہے کہ ذکرِ الٰہی عمل ہی ہے۔"],[297,"سیدنا معاذ بن جبل رضی اللہ عنہ فرماتے ہیں: ’’رسول اللہ صلی اللہ علیہ وسلم سے جدا ہوتے وقت میرا آپ صلی اللہ علیہ وسلم سے جو آخری مکالمہ ہوا تھا، وہ یہ تھا کہ میں نے کہا: ’’یارسول اللہ! اللہ تعالیٰ کے نزدیک سب سے پسندیدہ یا افضل اعمال کون سے ہیں؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’تمہیں اس حالت میں موت آئے کہ تمہاری زبان ذکرِ الٰہی سے تَر ہو۔‘‘","",{"k":"صحیح ابن حبان (818)۔ مسند الشامیین للطبرانی (1/122)۔ شعب الإیمان للبیھقي (1/393)"}],[298,"سیدنا عبداللہ بن مُغَفَّل رضی اللہ عنہ فرماتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ صلی اللہ علیہ وسلم اپنی اونٹنی یا اونٹ پر سوار ہو کر تلاوت کر رہے تھے۔ سواری چل رہی تھی اور آپ صلی اللہ علیہ وسلم سورۃ الفتح پڑھ رہے تھے یا سورۃ الفتح کا کچھ حصہ تلاوت کر رہے تھے۔ آپ صلی اللہ علیہ وسلم نرمی اور آہستگی کے ساتھ قراءت کر رہے تھے اور آواز کو حلق میں دہرا رہے تھے۔","",{"k":"صحیح البخاري (5047)۔ صحیح مسلم (794)"}],[299,"سیدنا عبد اللہ بن مغفل رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فتحِ مکہ کے روز ایک سورت کی تلاوت فرمائی اور اس میں ترجیع کی(یعنی حروف کو لمبا کیا۔) حدیث کے راوی معاویہ کہتے ہیں: ’’اگر تم چاہو کہ میں تمہارےسامنے رسول اللہ صلی اللہ علیہ وسلم کی قراءت جیسی قراءت کرکے دکھاؤں تو میں ایسا کرسکتا ہوں۔‘‘","",{"k":"صحیح البخاري (4835)"}],[300,"یہ روایت ابو الولید نے بھی شعبہ سےبیان کی ہے۔","",{"k":"صحیح البخاري (4281)"}],[301,"امام بخاری رحمہ اللہ فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم سے پوچھا گیا: ’’لوگوں میں سے اچھی قراءت والا کون ہے؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’وہ شخص کہ جب تم اسے تلاوت کرتے ہوئے سنو تو تمہیں لگے کہ وہ اللہ سے ڈر رہا ہے۔‘‘","",{"k":"سنن ابن ماجہ (1339)۔ أخلاق أھل القرآن للآجري، ص: 161، رقم: 83 عن جابر۔ حلیۃ الأولیاء وطبقات الأصفیاء لأبي نعیم: 3/317۔ شعب الإیمان للبیھقي: 2/388 عن ابن عباس۔ مسند عبد بن حمید: 2/35، رقم: 800۔ مختصر قیام اللیل للمروزي، ص: 138 عن ابن عمر"}],[302,"سعدبن ابی وقاص رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’پوشیدہ ذکر بہترین ذکر ہے۔‘‘","",{"k":"مسند أحمد: 1/172، 180، 187۔ الزھد لوکیع بن الجراح: 1/341، 2/616، رقم: 118، 339۔ مصنف ابن أبي شیبۃ: 10/375۔ سند ضعیف ہے۔"}],[303,"فرمان باری تعالیٰ ہے:\n﴿ وَٱذۡكُر رَّبَّكَ فِي نَفۡسِكَ تَضَرُّعًا وَخِيفَةً وَدُونَ ٱلۡجَهۡرِ مِنَ ٱلۡقَوۡلِ ﴾ [الأعراف: 205]\n’’اور (اے نبی) اپنے پروردگار کو صبح و شام دل ہی دل میں عاجزی، خوف کے ساتھ اور زبان سے بھی ہلکی آواز سے یاد کیا کیجئے۔‘‘\nدوسری جگہ فرمایا:\n﴿ ٱدۡعُواْ رَبَّكُمۡ تَضَرُّعًا وَخُفۡيَةًۚ ﴾ [الأعراف: 55]\n’’اپنے پروردگار کو گڑگڑاتے ہوئے اور چپکے چپکے پکارو۔‘‘"],[304,"سیدنا عمر رضی اللہ عنہ نے قاری معاذ کو اونچی آواز سے قراءت کرتے ہوئے سنا تو کہا:\n﴿ إِنَّ أَنكَرَ ٱلۡأَصۡوَٰتِ لَصَوۡتُ ٱلۡحَمِيرِ ﴾ [لقمان: 19]\n’’بیشک سب سے بری آواز گدھوں کی آواز ہے۔‘‘"],[305,"ابو عثمان کہتے ہیں: ’’مجھے چمٹے، باجے اور بانسری کی آواز بھی ابو موسیٰ کی آواز سے اچھی نہیں لگتی، سوائے فلاں شخص کے۔ وہ جب ہمیں نماز پڑھاتا ہے تو ہماری خواہش ہوتی ہے کہ سورۃ البقرۃ پڑھنا شروع کردے کیونکہ اس کی آواز بہت اچھی ہے۔‘‘","",{"k":"فضائل القرآن لأبي عبید (227)۔ مختصر قیام اللیل لمحمد بن نصر المروزي (ص 138)۔ حلیۃ الأولیاء وطبقات الأصفیاء لأبي نعیم (1/258)"}],[306,"معاذ رضی اللہ عنہ سے روایت ہے کہ انہوں نے کہا: ’’یا رسول اللہ! کیا ہم جو کچھ بولتے ہیں، اسی کی بناء پر ہمارا مؤاخذہ ہوگا اور وہ سب کچھ لکھا جاتا ہے؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’لوگوں کو جہنم میں نتھنوں کے بل ان کی زبانوں کی کاٹی ہوئی فصلیں ہی تو گرائیں گی۔‘‘","",{"k":"مسند أحمد (5/236)۔ المعجم الکبیر للطبراني (20/64، 73)۔ التمھید لابن عبد البر (5/66)"}],[307,"عبادہ بن صامت رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’لوگوں کو جہنم میں ان کی زبانوں کی بولی ہوئی باتیں ہی نتھنوں کے بل گرائیں گی۔‘‘","",{"k":"المستدرك للحاکم (4/286)۔ المختارۃ للضیاء المقدسي (8/333)"}],[308,"امام بخاری رحمہ اللہ فرماتے ہیں: ان روایات میں نبی کریم صلی اللہ علیہ وسلم نے اس بات کو واضح کردیا ہے کہ مخلوق کی آوازیں، ان کی قراءت، درس وتدریس، تعلیم اور زبانیں ایک دوسرے سے مختلف ہیں۔ کچھ آوازیں اچھی ہوتی ہیں، کچھ خوبصورت، کچھ پیاری، کچھ اونچی، کچھ زیادہ تلاوت کرنے والی، کچھ زیادہ لَے والی، کچھ بلند، کچھ زیادہ ہلکی، کچھ زیادہ آہستہ اور کچھ زیادہ پست ہوتی ہیں۔فرمان الٰہی ہے:\n﴿ وَخَشَعَتِ ٱلۡأَصۡوَاتُ لِلرَّحۡمَٰنِ فَلَا تَسۡمَعُ إِلَّا هَمۡسًا ﴾ [طہ: 108]\n’’اور اللہ رحمٰن کے سامنے تمام آوازیں پست ہوجائیں گی سوائے کھسر پھسر کے تجھے کچھ بھی سنائی نہ دے گا۔‘‘\nکچھ زیادہ بلند ہوتی ہیں، کچھ زیادہ مخفی، کچھ زیادہ تیزی سے چلنے والی، کچھ زیادہ لمبی، کچھ زیادہ نرم اور کچھ دوسروں کی نسبت ہلکی ہوتی ہیں۔"],[309,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”قرآن پڑھنے میں مہارت رکھنے والا ان بزرگ فرشتوں کے ساتھ ہوگا جو لوح محفوظ کے پاس لکھتے رہتے ہیں اور جسے قرآن پڑھنے میں مشقت ہوتی ہے، اس کےلیے دُگنا ثواب ہے۔“","",{"k":"صحیح البخاري (4937)۔ صحیح مسلم (798)"}],[310,"قتادہ کہتے ہیں کہ میں نے انس بن مالک رضی اللہ عنہ سے نبی کریم صلی اللہ علیہ وسلم کی قراءت کے بارے میں پوچھا تو انہوں نے فرمایا: ’’آپ صلی اللہ علیہ وسلم حروف کو لمبا کھینچ کرادا کرتے تھے۔‘‘","",{"k":"صحیح البخاري (5045)"}],[311,"دوسری سند سے یہی روایت مروی ہے اور اس میں انس رضی اللہ عنہ کا جواب یوں ہے کہ آپ صلی اللہ علیہ وسلم آواز کو لمبا کھینچتے تھے۔"],[312,"قتادہ کہتے ہیں کہ انس رضی اللہ عنہ سے پوچھا گیا کہ رسول اللہ صلی اللہ علیہ وسلم کی قراءت کیسی تھی؟ انہوں نے بیان کیا کہ مد کے ساتھ۔ پھر آپ رضی اللہ عنہ نے «بسم الله الرحمن الرحيم» پڑھا اور کہا کہ آپ صلی اللہ علیہ وسلم«بسم الله» (میں لفظ اللہ کی لام) کو مد کے ساتھ پڑھتے «الرحمن» (میں میم) کو مد کے ساتھ پڑھتے اور «الرحيم» (میں حاء کو) مد کے ساتھ پڑھتے۔","",{"k":"صحیح البخاري (5046)"}],[313,"سیدنا قُطْبہ بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فجر کی نماز میں یہ پڑھا:\n﴿ وَٱلنَّخۡلَ بَاسِقَٰتٍ لَّهَا طَلۡعٌ نَّضِيدٌ ﴾ [قٓ: 10]\n’’اور کھجوروں کے بلند و بالا درخت جن کے خوشے تہ بہ تہ ہیں۔‘‘\nاسے پڑھتے ہوئے آپ صلی اللہ علیہ وسلم نے اپنی آواز کو لمبا کیا۔","",{"k":"صحیح مسلم (457)"}],[314,"امام بخاری رحمہ اللہ فرماتے ہیں: جس چیز کی تلاوت ہوتی ہے، وہ اللہ تعالیٰ کا ایسا فرمان ہے کہ\n﴿ لَيۡسَ كَمِثۡلِهِۦ شَيۡءٌۖ وَهُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ ﴾ [الشوری: 11]\n’’کوئی چیز اس کے مثل نہیں ہے، اور وہی ہے جو ہر بات سنتا، سب کچھ دیکھتا ہے۔‘‘\nاور فرمان الٰہی ہے:\n﴿ هَٰذَا كِتَٰبُنَا يَنطِقُ عَلَيۡكُم بِٱلۡحَقِّۚ ﴾ [الجاثیۃ: 29]\n’’یہ ہماری کتاب جو تمہارے بارے میں سچ سچ بول رہی ہے۔‘‘"],[315,"سیدنا عبد اللہ بن عمرو رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’روزِ قیامت قرآن کو ایک مرد کی شکل میں لایا جائے گا اور وہ پڑھنے والے کی سفارش کرے گا۔‘‘"],[316,"اس روایت کی سند یہ ہے: زہیر بن حرب از یعقوب بن ابراہیم از ابراہیم از ابن اسحاق از عمرو بن شعیب از شعیب از عبد اللہ بن عمرو رضی اللہ عنہ۔"],[317,"امام بخاری رحمہ اللہ فرماتے ہیں کہ پڑھنا انسان کی کمائی اور اس کا فعل ہے۔ فرمان الٰہی ہے:\n﴿ فَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٍ خَيۡرًا يَرَهُۥ ٧ وَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٍ شَرًّا يَرَهُۥ ﴾ [الزلزلۃ: 7–8]\n’’چنانچہ جس نے ذرہ برابر کوئی اچھائی کی ہوگی، وہ اسے دیکھے گا۔ اور جس نے ذرہ برابر کوئی برائی کی ہوگی، وہ اسے دیکھے گا۔‘‘"],[318,"فَرَزْدَق کے چچا صَعْصَعہ کہتے ہیں کہ میں نبی کریم صلی اللہ علیہ وسلم کے پاس پہنچا تو میں نے آپ صلی اللہ علیہ وسلم کو مذکورہ بالا آیات کی تلاوت کرتے ہوئے سنا۔ میں نے کہا: ’’میرے لیے کافی ہے۔ مجھے پتہ چل گیا ہے کہ کس چیز میں خیر ہے اور کس چیز میں شر۔‘‘","",{"k":"السنن الکبری للنسائي: 6/520، رقم: 11694ْ۔ مسند أحمد: 5/59۔ الآحاد والمثاني لابن أبي عاصم: 2/402، رقم: 1197 – 1198"}],[319,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ فرماتے ہیں: ’’ہم تمہیں جب کوئی حدیث سناتے ہیں تو اس کا قرآنی مصداق بھی بتاتے ہیں۔‘‘ اس میں قراءتِ قرآن اور دیگر اعمال بھی شامل ہیں۔","",{"k":"تفسیر ابن جریر (22/120)۔ المعجم الکبیر للطبراني (9/233)۔ المستدرك للحاکم (2/425)"}],[320,"اللہ تعالیٰ نے درج ذیل آیت مبارک میں مخلوقات کے قول کو واضح کردیا ہے:\n﴿ لِيَبۡلُوَكُمۡ أَيُّكُمۡ أَحۡسَنُ عَمَلًاۚ ﴾ [الملك: 2]\n’’تاکہ وہ تمہیں آزمائے کہ تم میں سے کون عمل میں زیادہ بہتر ہے۔‘‘\nاس میں اللہ تعالیٰ نے بتایا ہے کہ عمل بھی زندگی کی تعریف میں شامل ہے۔ پھر اللہ تعالیٰ نے اپنی تخلیق کی وضاحت کرتے ہوئے فرمایا:\n﴿ وَأَسِرُّواْ قَوۡلَكُمۡ أَوِ ٱجۡهَرُواْ بِهِۦٓۖ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ١٣ أَلَا يَعۡلَمُ مَنۡ خَلَقَ وَهُوَ ٱللَّطِيفُ ٱلۡخَبِيرُ ﴾ [الملك: 13–14]\n’’تم اپنی باتوں کو چھپاؤ یا ظاہر کرو، وہ تو سینوں کی پوشیدگی کو بھی بخوبی جانتا ہے۔بھلا جس نے پیدا کیا وہی نہ جانے؟ جبکہ وہ بہت باریک بین، مکمل طور پر باخبر ہے۔‘‘"],[321,"جبکہ جہمیہ اور معطلہ کا اہل علم سے اللہ کے کلام کے بارے میں یہ جھگڑاہے کہ اللہ تعالیٰ کلام نہیں کرتے۔ اور اگر کلام کریں تو وہ کلام، اللہ کی مخلوق ہوگی۔ وہ اس بات کے قائل ہیں کہ اللہ کے علم سے پڑھا جانے والا قرآن مخلوق ہے۔ اس قول کے مطابق ان کے نزدیک بندوں کی تلاوت اور پڑھی جانے والی چیز میں کوئی فرق نہیں ہے۔"],[322,"حالانکہ ابو بکر رضی اللہ عنہ نے اللہ تعالیٰ کے اس فرمان کو بآوازِ بلند پڑھا تھا:\n﴿ أَتَقۡتُلُونَ رَجُلًا ﴾ [غافر: 28]\n’’کیا تم ایک آدمی کو قتل کرنا چاہتے ہو؟‘‘\nاس روایت کو عبد اللہ بن عمرو بن عاص رضی اللہ عنہ نے روایت کیا ہے۔ وہ کہتے ہیں: ’’میرے علم کے مطابق قریش نے صرف ایک مرتبہ آپ صلی اللہ علیہ وسلم کو قتل کرنے کا ارادہ کیا تھا۔ یہ دیکھ کر ابو بکر آگے بڑھے اور انہوں نے آپ صلی اللہ علیہ وسلم کو چھڑوایا، پھر بآوازِ بلند فرمایا:\n﴿ أَتَقۡتُلُونَ رَجُلًا أَن يَقُولَ رَبِّيَ ٱللَّهُ وَقَدۡ جَآءَكُم بِٱلۡبَيِّنَٰتِ مِن رَّبِّكُمۡۖ ﴾ [غافر: 28]\n’’کیا تم ایک شخص کو صرف اس لیے قتل کر رہے ہو کہ وہ کہتا ہے: ’’میرا پروردگار اللہ ہے؟‘‘\nحالانکہ وہ تمہارے پاس تمہارے پروردگار کی طرف سے روشن دلائل لے کر آیا ہے۔‘‘\nاس موقع پر آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! میرے رب نے مجھے تمہارے پاس (تمہارے) ذبح کرنے کےلیے بھیجا ہے۔‘‘ ابو جہل کہنے لگا: ’’اے محمد! تم تو نادان نہیں تھے۔‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’تو بھی انہی لوگوں میں شامل ہے۔‘‘","",{"k":"دلائل النبوۃ لأبي نعیم (159)۔ مصنف ابن أبي شیبۃ (14/297)۔ صحیح ابن حبان (14/529)"}],[323,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ ابو بکر رضی اللہ عنہ کھڑے ہوئے اور اونچی آواز سے کہنے لگے: ’’تمہارا ستیا ناس ہوجائے۔ ﴿ أَتَقۡتُلُونَ رَجُلًا أَن يَقُولَ رَبِّيَ ٱللَّهُ ﴾ کیا تم ایک آدمی کو صرف اس لیے قتل کرنا چاہتے ہو کہ وہ کہتا ہے: میرا رب اللہ ہے؟‘‘","",{"k":"فضائل الصحابۃ لأحمد (218)۔ مسند أبي یعلیٰ (3691)۔ المستدرك للحاکم (3/67)"}],[324,"یہ روایت عبد اللہ بن عمرو اور اسماء بنت ابی بکر نے بھی نبی کریم صلی اللہ علیہ وسلم کے حوالہ سے بیان کی ہے۔","",{"k":"صحیح البخاري (3678) عن عبد اللہ بن عمرو بن العاص۔ مسند الحمیدي: 1/155، رقم: 324۔ سنن سعید بن منصور: 2/371۔ الآحاد والمثاني لابن أبي عاصم: 1/79، رقم: 25 عن أسماء بنت أبي بکر"}],[325,"امام بخاری رحمہ اللہ فرماتے ہیں: جو کچھ پڑھا گیا، وہ اس رب کا کلام ہے جس نے موسیٰ علیہ السلام سے کہا تھا:\n﴿ إِنَّنِيٓ أَنَا ٱللَّهُ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعۡبُدۡنِي ﴾ [طہ: 14]\n’’حقیقت یہ ہے کہ میں ہی اللہ ہوں۔ میرے سوا کوئی معبود نہیں ہے، اس لیے میری عبادت کرو۔‘‘\nجبکہ معتزلہ کا دعویٰ ہے کہ اللہ کا فعل مخلوق ہے اور بندوں کے افعال غیر مخلوق ہیں۔ یہ نظریہ مسلمانوں کے علم کے خلاف ہے۔ البتہ وہ بصری اس نظریہ کے قائل ہیں جو سَنْسویہ کی باتوں سے چمٹے ہوئے ہیں۔ یہ پہلے مجوسی تھا۔ پھر اسلام کا دعویدار بن بیٹھا۔ حسن کہتے ہیں: ’’ان بصریوں کو عجمیت نے تباہ وبرباد کردیا۔‘‘"],[326,"حسن کے قول کی سند یہ ہے: سلیمان بن حرب از حماد بن زیداز ابن زید نُمَیرِی از حسن۔","",{"k":"التاریخ الکبیر للبخاري (5/93 – 94)"}],[327,"قتادہ کا قول ہے کہ اہلِ عرب زمانہ جاہلیت اور اسلام دونوں میں تقدیر کا اثبات کرنے والے رہے ہیں۔","",{"k":"الإبانۃ لابن بطۃ (1792)"}],[328,"اللہ عز وجل کا فرمان گرامی ہے:\n﴿ يَٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغۡ مَآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَۖ وَإِن لَّمۡ تَفۡعَلۡ فَمَا بَلَّغۡتَ رِسَالَتَهُۥۚ وَٱللَّهُ يَعۡصِمُكَ مِنَ ٱلنَّاسِۗ ﴾ [المائدۃ: 67]\n’’اے رسول! جو کچھ آپ کے پروردگار کی طرف سے آپ پر نازل کیا گیا ہے اسے لوگوں تک پہنچا دیجئے۔ اور اگر آپ نے ایسا نہ کیا تو اللہ کا پیغام پہنچانے کا حق ادا نہ کیا۔ اور اللہ آپ کو لوگوں (کے شر) سے محفوظ رکھے گا۔‘‘\nمذکورہ بالا آیت میں اللہ تعالیٰ نے پہلے نازل شدہ وحی کی تبلیغ کا تذکرہ کیا اور پھر پیغام پہنچانے کے فعل کا ذکر کیا اورفرمایا: ﴿ وَإِن لَّمۡ تَفۡعَلۡ فَمَا بَلَّغۡتَ رِسَالَتَهُۥۚ ﴾ اس طرح اللہ تعالیٰ نے پیغام پہنچانے یا نہ پہنچانے کو فعل قرار دیا ہے۔ اب کسی آدمی کےلیے ممکن نہیں ہے کہ وہ رسول پر اعتراض کرتے ہوئے کہے کہ انہیں پیغام پہنچانے کا جو حکم دیا گیا تھا، انہوں نے وہ کام نہیں کیا۔"],[329,"سیدنا عبد اللہ بن عباس رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے یوم النحر (10 ذو الحجہ) کو لوگوں سے خطاب کیا، پھر آسمان کی طرف سر اٹھایا اور فرمایا: ’’اے اللہ! کیا میں نے پہنچا دیا؟ یا اللہ! کیا میں نے پیغام دے دیا؟ الٰہی! کیا میں نے تبلیغ کردی؟‘‘ ابن عباس رضی اللہ عنہ فرماتے ہیں: ’’اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! بلاشبہ آپ صلی اللہ علیہ وسلم نے اپنی امت کو وصیت فرمائی تھی: ’’جو بندہ یہاں موجود ہے، وہ غیر موجود تک پہنچا دے۔‘‘","",{"k":"صحیح البخاري (1739) و 7079۔ یہ روایت آگے 410 نمبر پر بھی آئے گی۔"}],[330,"سیدنا مالک بن نضلہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہواتو آپ صلی اللہ علیہ وسلم نے مجھے اوپر سے نیچے تک دیکھا۔ میں نے پوچھا: ’’آپ کس چیز کی دعوت دیتے ہیں اور کن باتوں سے منع کرتے ہیں؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ تعالیٰ کے علاوہ کوئی چیز نہیں ہے اور صلہ رحمی کرو۔‘‘ آپ صلی اللہ علیہ وسلم نے یہ بھی فرمایا: ’’میرے پاس میرے رب کی طرف سے پیغامِ رسالت آیا تو اس سے میرا دل بہت تنگ ہوا۔ میرا خیال تھا کہ جلد ہی لوگ میری تکذیب کریں گے۔ تو مجھے کہا گیا: ’’آپ صلی اللہ علیہ وسلم پیغامِ رسالت کو ضرور پہنچائیں گے، یا پھر آپ صلی اللہ علیہ وسلم کے ساتھ ضرور وہ (سختی والا معاملہ) کیا جائے گا۔‘‘","",{"k":"مسند الحمیدي (883)"}],[331,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’میری طرف سے پہنچا دو اگرچہ ایک آیت ہی ہو۔‘‘","",{"k":"ذم الکلام وأھلہ للھروي: 2/92 – 93، رقم: 184۔ سند ضعیف ہے۔ متن دیگر صحابہ سے مروی روایات کے مطابق صحیح ہے۔"}],[332,"امام زہری رحمہ اللہ فرماتے ہیں: ’’اللہ تعالیٰ کی طرف سے پیغام آیا جسے پہنچانا رسول اللہ صلی اللہ علیہ وسلم کی ذمہ داری تھی اور اسے تسلیم کرنا ہمارا فرض ہے۔‘‘","",{"k":"صحیح البخاري: 13/503 معلقاً۔ تعظیم قدر الصلاۃ للمروزي: 1/487۔ السنۃ للخلال: 3/579"}],[333,"امام بخاری رحمہ اللہ فرماتے ہیں: کچھ لوگوں نے بغیر غور وفکر اور صحیح تقلید کے اس کلام کو اختیار کرلیا ہے جس کی وجہ سے وہ اتنے فرقوں میں بٹ گئے ہیں کہ میں انہیں شمار بھی نہیں کرسکتا۔ چنانچہ انہوں نے جہالت کی بناء پر بغیر دلیل اور سند کے ایک دوسرے کوگمراہ کردیا ہے۔ سوائے اس کے جس پر تیرا رب رحم فرما دے۔ یہ ساری باتیں غیر اللہ کی طرف سے ہیں، اس لیے انہیں اس میں بہت سا اختلاف ملا ہے۔ جب اللہ تعالیٰ نے انہیں فرقوں میں بانٹنے اور ایک دوسرے کے ذریعہ مزہ چکھانےکا فیصلہ کرلیا ہے تو اب اسے کوئی ٹال نہیں سکتا۔ اس لیے وہ اپنے بےچینی پیدا کرنے والے شک میں گھوم پھر رہے ہیں۔ جیسا کہ:"],[334,"عبد اللہ بن ذکوان قرشی المعروف ابو الزناد (المتوفیٰ: 130ھ) فرماتے ہیں: ’’وہ کسی چیز پر نہیں ٹھہرتے اگرچہ انہیں پسند بھی ہو، مگر بحث مباحثہ انہیں اس کے علاوہ کسی اور چیز کی طرف لے جاتا ہے۔ اس طرح وہ روزانہ ایک نئے شبہے اور گمراہ دین میں پڑ جاتے ہیں۔‘‘"],[335,"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ جب یہ آیت: ﴿ قُلۡ هُوَ ٱلۡقَادِرُ عَلَىٰٓ أَن يَبۡعَثَ عَلَيۡكُمۡ عَذَابًا مِّن فَوۡقِكُمۡ أَوۡ ﴾ ’’آپ ان سے کہیے: کہ اللہ اس بات پر قادر ہے کہ وہ تم پر تمہارے اوپر سے کوئی عذاب نازل کرے۔‘‘نازل ہوئی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ اے اللہ! میں تیرے چہرے کی پناہ مانگتا ہوں۔ پھر یہ اترا: ﴿ مِن تَحۡتِ أَرۡجُلِكُمۡ أَوۡ ﴾ ’’یا تمہارے پاؤں کے نیچے سے تم پر کوئی عذاب مسلط کردے۔‘‘آپ صلی اللہ علیہ وسلم نے فرمایا کہ یا اللہ! میں تیرے چہرے کی پناہ مانگتا ہوں۔ پھر یہ نازل ہوا:\n﴿ يَلۡبِسَكُمۡ شِيَعًا وَيُذِيقَ بَعۡضَكُم بَأۡسَ بَعۡضٍۗ ﴾ [الأنعام: 65]\n’’یا تمہیں فرقے فرقے بنا کر ایک فرقے کو دوسرے سے لڑائی (کا مزا) چکھا دے۔‘‘\nاس وقت نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’یہ پہلے عذابوں سے ہلکا یا آسان ہے۔‘‘","",{"k":"صحیح البخاري (4628، 7406)"}],[336,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’اللہ عز وجل نے تمام خواہش پرستوں پر اس چیز کو حرام کردیا ہے کہ وہ اپنے ساتھیوں یا اپنی اسانید کے ذریعہ رسول اللہ صلی اللہ علیہ وسلم کے احکام میں سے کوئی حکم اور فرض یا رسولوں کی سنتوں میں سے کوئی سنت حاصل کریں۔ بس وہ ان لوگوں کی طرح جنہوں نے قرآن کے حصے بخرے کرلیے تھے کہ کسی حصے کو مان لیا اور کسی کا انکار کردیا، محدثین سے اپنی پسند کی باتیں اخذ کرلیتے ہیں۔ اس لیے جو بندہ اہل علم کی نقل کردہ کسی سنت کو رد کرتا ہے، اس پر لازم ہے کہ بقیہ سنتوں کا بھی انکار کرے یہاں تک کہ ساری سنتوں، کتاب اللہ اور احکامِ اسلام سے فارغ ہوجائے۔ اس کی تفصیل بہت لمبی ہے۔"],[337,"خلیل بن احمد کا قول ہے: ’’مختصر بات اس لیے کی جاتی ہے تاکہ یاد رہے اور لمبی اس لیے کی جاتی ہے تاکہ سمجھ میں آجائے۔‘‘","",{"k":"المدخل إلی السنن الکبری للبیھقي (596)"}],[338,"ہم تو عمر رضی اللہ عنہ کے مسلک پر ہیں جنہوں نے کہا تھا: ’’میں وہ بات کہنے لگا ہوں جسے کہنا میرے مقدر میں ہے۔جس کی سمجھ میں آجائے اور وہ اسے یاد کرلے تو اس پر لازم ہے کہ جہاں تک اس کی سواری اسے لے جاسکے، وہاں تک پہنچا دے۔ اور جسے یہ ڈر ہو کہ اسے صحیح طرح یاد نہیں رہا، تو میری طرف سے اسے بالکل بھی اجازت نہیں ہے کہ میرے اوپر جھوٹ باندھے۔‘‘ اس قول کی سند یہ ہے: یحییٰ بن سلیمان از ابن وہب از مالک ویونس از ابن شہاب از عبید اللہ بن عبد اللہ از ابن عباس از عمر رضی اللہ عنہ۔","",{"k":"صحیح البخاري (6830)"}],[339,"اللہ تبارک وتعالیٰ کا فرمان ہے: ﴿ وَلَا تَقۡفُ مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌۚ ﴾ [الإسراء: 36]\n’’اور ایسی بات کے پیچھے نہ پڑو جس کا تجھے علم نہیں۔‘‘"],[340,"اللہ تعالیٰ ہمیں اور آپ کو صراط مستقیم کی ہدایت نصیب فرمائے اور ہمیں ان لوگوں سے بچا کر رکھے جنہوں نے تفرقہ بازی کی اور واضح نشانیاں آجانے کے بعد اختلاف کیا۔"],[341,"سیدنا اُبَی بن کعب رضی اللہ عنہ اللہ تعالیٰ کے فرمان:\n﴿ بَغۡيَۢا بَيۡنَهُمۡۚ ﴾ [الجاثیۃ: 17]\n’’آپس کی ضد بحث کی وجہ سے۔‘‘\nکی تفسیر کرتے ہوئے فرماتے ہیں: ’’دنیا پر سرکشی کرکے، اس کے ملک حاصل کرکے اور اس کی زیب وزینت کو اپنا کر کہ بادشاہت کس کی ہوگی اور لوگوں پر ہیبت کس کی طاری ہوگی۔ چنانچہ انہوں نے ایک دوسرے پر سرکشی کی اور ایک دوسرے کی گردنیں کاٹیں۔ پھر اللہ تعالیٰ نے ایمان داروں کو اپنے حکم سے، جن چیزوں میں وہ اختلاف کررہے تھے، حق کی ہدایت نصیب فرمائی، جس کی وجہ سے وہ رسولوں کے لائے ہوئے دین پر قائم ہوگئے۔ انہوں نے نماز قائم کی، زکاۃ ادا کی اور اختلاف سے دور ہی رہے۔ یہی لوگ روزِ قیامت دوسرے لوگوں کے خلاف گواہی دیں گے کہ ان کے رسولوں نے انہیں پیغامِ الٰہی پہنچا دیا تھا اور انہوں نے اپنے رسولوں کو جھٹلایا تھا۔‘‘","",{"k":"تفسیر ابن أبي حاتم (1991، 1993)"}],[342,"سیدنا عمرو بن عوف رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سب مل کر اللہ کی رسی کو مضبوطی سے تھام لو اور تفرقہ بازی میں نہ پڑو۔ ان لوگوں کی طرح نہ ہوجانا جنہوں نے واضح نشانیاں آجانے کے بعد اختلاف کیا۔‘‘","",{"k":"المعجم الکبیر للطبراني (17/12)"}],[343,"سیدنا عبد اللہ بن عمر رضی اللہ عنہ فرماتے ہیں: ’’ایک مرتبہ میں کہیں جارہا تھا کہ اچانک ایک شخص سامنے آگیا اور اس نے پوچھا: ’’ابن عمر! تم نے نبی کریم صلی اللہ علیہ وسلم سے سرگوشی کے بارے میں کیا سنا ہے؟‘‘ میں نے کہا: ’’نبی کریم صلی اللہ علیہ وسلم فرماتے تھے: ’’ایک مؤمن اپنے پروردگار کے نزدیک ہو جائے گا۔ پروردگار اپنا پردہ اس پر ڈال دے گا۔‘‘ ابن عمر کہتے ہیں کہ اللہ تعالیٰ اس کے نامہ اعمال کا تذکرہ کریں گے اور اس سے اس کے گناہوں کا اقرار کروائیں گے اور پوچھیں گے: ’’اس گناہ کو جانتے ہو؟‘‘ بندہ کہے گا: ’’میرے رب! جانتا ہوں۔‘‘ اللہ تعالیٰ پھر دوسرے گناہ کا پوچھیں گے۔ بندہ اس کا بھی اقرار کرے گا۔ یہاں تک کہ تمام گناہوں کا اعتراف کرلے گا۔ پھر اللہ تعالیٰ فرمائیں گے: ’’میں نے دنیا میں تمہارے گناہوں کا پردہ رکھا تھا، آج انہیں معاف کررہا ہوں۔‘‘ چنانچہ اسے نیکیوں والا نامہ اعمال دیا جائے گا۔ جبکہ کافر کو تمام لوگوں کے سامنے بلایا جائے گا۔فرمان باری تعالیٰ ہے:\n﴿ وَيَقُولُ ٱلۡأَشۡهَٰدُ هَٰٓؤُلَآءِ ٱلَّذِينَ كَذَبُواْ عَلَىٰ رَبِّهِمۡۚ أَلَا لَعۡنَةُ ٱللَّهِ عَلَى ٱلظَّٰلِمِينَ ﴾ [ھود: 18]\n’’اور سارے گواہ کہیں گے کہ یہ وہ لوگ ہیں جنہوں نے اپنے پروردگار پر جھوٹ باندھا۔ سن لو! ظالموں پر اللہ کی لعنت ہے۔‘‘\nابن مبارک رحمہ اللہ فرماتے ہیں: ’’حدیث کے لفظ «کنفہ» کا مطلب ہے: ’’اللہ کا پردہ۔‘‘","",{"k":"صحیح البخاري (2441)۔ صحیح مسلم (2768)\nالزھد لابن المبارك (166)۔ حاشیۃ (2)"}],[344,"مسلم از ابان از قتادہ از صفوان بن محرز کی سندسے درج ذیل الفاظ مروی ہیں۔ صفوان بن محرز کہتے ہیں کہ ایک مرتبہ میں ابن عمر رضی اللہ عنہ کے ساتھ جارہا تھا تو انہوں نے فرمایا کہ میں نے نبی کریم صلی اللہ علیہ وسلم سے سنا ہے۔ پھر مذکورہ بالا حدیث سنائی۔"],[345,"مسدد از ابو عوانہ از قتادہ کی سند سے بھی یہ روایت مروی ہے۔","",{"k":"صحیح البخاري (6070، 7514)"}],[346,"مسدد از یزید بن زریع از سعید وہشام از قتادہ کی سند سے بھی یہ روایت مروی ہے۔","",{"k":"صحیح البخاري (4685)"}],[347,"آدم از شیبان از قتادہ از صفوان بن محرز از ابن عمر کی سند سے بھی یہ روایت مروی ہے۔","",{"k":"صحیح البخاري (7514) کے بعد"}],[348,"سیدنا عبد اللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے نبی کریم صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ’’جہاں تک کافر اور منافق کی بات ہے تو تمام گواہ کہیں گے: ’’یہ وہ لوگ ہیں جنہوں نے اپنے رب پر جھوٹ بولا تھا۔ خبردار! ظالموں پر اللہ کی لعنت ہو۔‘‘","",{"k":"صحیح البخاري (2441)"}],[349,"شُفَیَّا اصبحی بیان کرتے ہیں کہ میں مدینہ گیا تو وہاں ابو ہریرہ رضی اللہ عنہ نے بیان کیا کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے بتایا: ’’اللہ تعالیٰ روزِ قیامت قاری سے فرمائیں گے: ’’کیا میں نے تجھے اپنے رسول پر نازل کردہ کتاب نہیں سکھائی تھی؟‘‘ وہ کہے گا: ’’کیوں نہیں میرے رب!‘‘ اللہ تعالیٰ پوچھیں گے: ’’پھر تم نے کیا عمل کیا؟‘‘ وہ کہے گا: ’’میں رات دن قیام کرتا تھا۔‘‘ اللہ تعالیٰ فرمائیں گے: ’’غلط کہتے ہو۔‘‘ فرشتے بھی کہیں گے: ’’تم جھوٹ بولتے ہو۔‘‘ اللہ تعالیٰ فرمائیں گے: ’’تمہارا تو صرف اتنا مفاد تھا کہ تمہیں قاری کہا جائے، تو تجھے قاری کہہ دیا گیا۔ ‘‘ حدیث کے راوی ابو عثمان کہتے ہیں کہ مجھے علاء بن ابی حکیم نے بتایا کہ معاویہ رضی اللہ عنہ نے فرمایا: ’’اللہ اور اس کے رسول صلی اللہ علیہ وسلم نے بالکل سچ کہا ہے:\n﴿ مَن كَانَ يُرِيدُ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا وَزِينَتَهَا نُوَفِّ إِلَيۡهِمۡ أَعۡمَٰلَهُمۡ فِيهَا وَهُمۡ فِيهَا لَا يُبۡخَسُونَ ١٥ أُوْلَٰٓئِكَ ٱلَّذِينَ لَيۡسَ لَهُمۡ فِي ٱلۡأٓخِرَةِ إِلَّا ٱلنَّارُۖ وَحَبِطَ مَا صَنَعُواْ فِيهَا وَبَٰطِلٌ مَّا كَانُواْ يَعۡمَلُونَ ﴾ [ھود: 15–16]\n’’جو لوگ (صرف) دنیوی زندگی اور اس کی سج دھج چاہتے ہیں، ہم ان کے اعمال کا پورا پورا صلہ اسی دنیا میں بھگتا دیں گے، اور یہاں ان کے حق میں کوئی کمی نہیں ہوگی۔ ہاں یہی وہ لوگ ہیں جن کے لئے آخرت میں سوائے آگ کے اور کچھ نہیں اور جو کچھ انہوں نے یہاں کیا ہوگا وہاں سب اکارت ہے اور جو کچھ اعمال تھے، سب برباد ہونے والے ہیں۔‘‘"],[350,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’مصاحف کی خرید وفروخت سے متعلق شعبی کے قول: ’’مصحف فروخت کرنے والا اپنے ہاتھ کی کارگزاری بیچتا ہے۔‘‘ کی زیاد بن لبید کا قول تائید کرتا ہے جس کی تفصیل یہ ہے کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے پوچھا: ’’علم کیسے اٹھا لیا جائے گا حالانکہ وہ پختہ ہوچکا ہے اور دل اسے محفوظ کرچکے ہیں۔۔۔ الخ‘‘"],[351,"عوف بن مالک اشجعی رضی اللہ عنہ بیان کرتے ہیں کہ ایک دن نبی کریم صلی اللہ علیہ وسلم نے آسمان کی طرف نظر اٹھائی اور فرمایا: ’’یہ علم کے اٹھنے کا وقت ہے۔‘‘ زیاد بن لبید نامی ایک انصاری شخص نے عرض کیا: ’’یا رسول اللہ! علم کیسے اٹھ سکتا ہے حالانکہ وہ مضبوط ہوچکا ہے اور دلوں میں محفوظ ہوچکا ہے؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’میں تو تمہیں مدینہ کے سمجھدار افراد میں سے سمجھتا تھا۔۔۔‘‘ پھر آپ صلی اللہ علیہ وسلم نے یہود ونصاریٰ کے ہاتھوں میں کتاب اللہ کی موجودگی کے باوجود ان کی گمراہی کا تذکرہ کیا۔جبیر بن نفیر کہتے ہیں کہ پھر شداد بن اوس سے میری ملاقات ہوئی تو میں نے انہیں عوف کی حدیث سنائی۔ انہوں نے فرمایا: ’’میں تمہیں بتاؤں کہ سب سے پہلے کون سی چیز اٹھائی جائے گی؟‘‘ میں نے کہا: ’’ضرور۔‘‘ انہوں نے فرمایا: ’’سب سے پہلے خشوع اٹھے گا، یہاں تک کہ تمہیں کوئی خشوع والا بندہ نہیں ملے گا۔‘‘","",{"k":"مسند البزار (7/175)۔ المعجم الکبیر للطبراني (18/43)۔ مسند الشامیین للطبراني (1/55)"}],[352,"یحییٰ بن بُکَیر نے یہی حدیث لیث کے حوالہ سے بیان کی ہے۔","",{"k":"المعجم الکبیر للطبراني (18/43)۔ المستدرك للحاکم (1/98 – 99)"}],[353,"ایک اور سند سے یہی روایت عوف بن مالک رضی اللہ عنہ سے مروی ہے، وہ کہتے ہیں کہ ایک مرتبہ ہم نبی کریم صلی اللہ علیہ وسلم کے پاس بیٹھے ہوئے تھے۔ پھر مذکورہ بالا واقعہ انہوں نے بیان کیا۔ اس میں زیاد کے الفاظ یہ ذکر ہوئے ہیں: ’’علم کیسے اٹھ سکتا ہے جبکہ کتاب اللہ ہمارے پاس ہے اور ہم اپنے بچوں اور بچیوں کو سکھا رہے ہیں؟‘‘","",{"k":"مسند أحمد (6/26)"}],[354,"ابو وائل کہتے ہیں کہ میں ابو موسیٰ اور عبد اللہ بن مسعود رضی اللہ عنہما کے ساتھ تھا۔ دونوں نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’قیامت سے پہلے ایسا زمانہ بھی آئے گا کہ جس میں جہالت عام ہوجائے گی اور علم اٹھ جائے گا۔‘‘","",{"k":"صحیح البخاري (7062، 7063)۔ صحیح مسلم (2672)"}],[355,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’علم کا اٹھ جانا قیامت کی نشانیوں میں سے ایک نشانی ہے۔‘‘","",{"k":"صحیح البخاري (80)۔ صحیح مسلم (2671)"}],[356,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’علم کا اٹھنا اور جہالت کا پھیلنا قیامت کی نشانی ہے۔‘‘","",{"k":"صحیح البخاري (81)"}],[357,"مسلم از ہشام از قتادہ کی سند سے بھی یہی الفاظ مروی ہیں۔","",{"k":"صحیح البخاري (5577)"}],[358,"یہی الفاظ سیدنا عبد اللہ بن عمر رضی اللہ عنہ نے بھی نبی کریم صلی اللہ علیہ وسلم سے روایت کیے ہیں۔","",{"k":"مسند البزار بحوالہ مجمع الزوائد: 1/200۔ ایک راوی سعد بن سنان مختلف فیہ ہے۔"}],[359,"یہی روایت سیدنا ابو ہریرہ رضی اللہ عنہ کے واسطہ سے بھی آپ صلی اللہ علیہ وسلم سے مروی ہے۔","",{"k":"صحیح البخاري (6037)۔ صحیح مسلم (157)"}],[360,"سیدنا عمر رضی اللہ عنہ فرماتے ہیں: ’’اُبَیّ ہمارے سب سے بڑے قاری ہیں۔ ہم ان کی بہت سی قراءت چھوڑ دیتے ہیں۔‘‘","",{"k":"کیونکہ ابی رضی اللہ عنہ فرماتے تھے کہ میں رسول اللہ صلی اللہ علیہ وسلم سے سنی ہوئی کوئی چیز نہیں چھوڑ سکتا، حالانکہ اللہ تعالیٰ نے فرمایا ہے کہ ہم کوئی آیت منسوخ کرتے ہیں یا بھلا دیتے ہیں تو اس سے بہتر یا اس جیسی کوئی آیت لے آتے ہیں۔"}],[361,"سیدنا عبد اللہ بن عباس رضی اللہ عنہ سے بھی ایسی ہی بات مروی ہے۔","",{"k":"صحیح البخاري (5005، 4481)"}],[362,"سیدنا عبد اللہ بن عباس رضی اللہ عنہ آیت کریمہ:\n﴿ وَلَا تَجۡهَرۡ بِصَلَاتِكَ وَلَا تُخَافِتۡ بِهَا ﴾ [الإسراء: 110]\n’’اور تم اپنی نماز نہ بہت اونچی آواز سے پڑھو، اور نہ بہت پست آواز سے‘‘\nکے بارے میں فرماتے ہیں کہ یہ مکہ میں نازل ہوئی تھی۔ رسول اللہ صلی اللہ علیہ وسلم جب اونچی آواز سے قرآن مجید کی تلاوت کرتے تھے تو مشرکین قرآن نازل کرنے والے اور لانے والے دونوں کو برا بھلا کہتے تھے۔ ﴿ وَلَا تُخَافِتۡ بِهَا ﴾ ’’اور نہ بہت پست آواز سے‘‘ اپنے ساتھیوں کے سامنے یہاں تک کہ وہ آپ صلی اللہ علیہ وسلم سے قرآن اخذ کرلیں۔","",{"k":"سنن الترمذي: 5/306۔ ترمذی میں ابن عباس رضی اللہ عنہ کا واسطہ نہیں ہے۔"}],[363,"سیدنا عبد اللہ بن عباس رضی اللہ عنہ مذکورہ بالا آیت کا شانِ نزول بیان کرتے ہوئے فرماتے ہیں: ’’رسول اللہ صلی اللہ علیہ وسلم تلاوت قرآن کرتے ہوئے آواز بلند کرتے تو مشرکین قرآن اور اسے لانے والے دونوں کو برا بھلا کہتے۔ یہ بات مسلمانوں کو پسند نہیں تھی۔ جب آپ صلی اللہ علیہ وسلم آواز پست کرتے تو صحابہ کرام رضی اللہ عنہم کےلیے بہت مشکل ہوجاتی۔ اس پر اللہ عز وجل نے مذکورہ آیت نازل فرمائی۔‘‘","",{"k":"أیضاً"}],[364,"سیدنا عبد اللہ بن عباس رضی اللہ عنہ مذکورہ بالا آیت کی وضاحت میں فرماتے ہیں: ’’جس وقت یہ آیت نازل ہوئی، اس وقت رسول اللہ صلی اللہ علیہ وسلم مکہ میں چھپ کر دین کی تبلیغ کررہے تھے۔ جب کبھی اپنے صحابہ کو نماز پڑھاتے ہوئے آپ صلی اللہ علیہ وسلم اونچی آواز سے قرآن پڑھتے اور مشرک سن لیتے تو وہ قرآن کو، اسے نازل کرنے والے اور لانے والے سب کو برا بھلا کہتے۔ اس پر اللہ تعالیٰ نے اپنے نبی صلی اللہ علیہ وسلم سے کہا: ﴿ وَلَا تَجۡهَرۡ بِصَلَاتِكَ ﴾ یعنی نماز پڑھتے ہوئے اپنی آواز کو اتنا اونچا نہ کیجیے کہ مشرک سن لیں اور پھر قرآن کو برا بھلا کہیں۔ ﴿ وَلَا تُخَافِتۡ بِهَا ﴾ یعنی اپنے صحابہ کے سامنے اتنی آہستہ آواز میں بھی قراءت نہ کیجیے کہ انہیں سنائی ہی نہ دے۔\n﴿ وَٱبۡتَغِ بَيۡنَ ذَٰلِكَ سَبِيلًا ﴾ [الإسراء: 110]\n’’بلکہ ان دونوں کے درمیان (معتدل) راستہ اختیار کرو۔‘‘","",{"k":"صحیح البخاري (7525، 4722)۔ صحیح مسلم (446)"}],[365,"یہی روایت اعمش نے جعفر بن ایاس سے نقل کی ہے۔","",{"k":"سنن النسائي (2/178)۔ تفسیر ابن جریر (15/185)۔ المعجم الکبیر للطبراني (12/55)"}],[366,"سیدنا عبد اللہ بن عباس رضی اللہ عنہ فرماتے ہیں کہ مذکورہ بالا آیت مشرکین کی وجہ سے نازل ہوئی۔ اللہ تعالیٰ فرماتے ہیں: ﴿ وَلَا تَجۡهَرۡ بِصَلَاتِكَ ﴾ دورانِ نماز اپنی آواز کو اتنا بلند نہ کیجیے کہ مشرکین آپ صلی اللہ علیہ وسلم سے دور چلے جائیں۔ ﴿ وَلَا تُخَافِتۡ بِهَا ﴾ اتنی آہستہ آواز سے بھی تلاوت نہ کیجیے کہ ان میں سے جو چوری چھپے تلاوت سننا پسند کرتے ہیں، انہیں آواز ہی سنائی نہ دے۔ ہوسکتا ہے کہ جو کچھ وہ سنے، اس میں سے کچھ اس کے دل کو لگ جائے جو اسے نفع دے۔","",{"k":"سیرۃ ابن ھشام (1/314)۔ تفسیر ابن جریر (15/185)"}],[367,"سیدنا عبد اللہ بن عباس رضی اللہ عنہ فرماتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم مکہ میں جب قرآن مجید کی بآواز بلند تلاوت فرماتے تو مشرکین لوگوں کو آپ صلی اللہ علیہ وسلم سے دور بھگا دیتے اور کہتے:\n﴿ لَا تَسۡمَعُواْ لِهَٰذَا ٱلۡقُرۡءَانِ وَٱلۡغَوۡاْ فِيهِ لَعَلَّكُمۡ تَغۡلِبُونَ ﴾ [فصلت: 26]\n’’اس قرآن کو سنو ہی نہیں، اور اس کے بیچ میں غل مچا دیا کرو تاکہ تم ہی غالب رہو۔‘‘\nاور جب آپ صلی اللہ علیہ وسلم ہلکی آواز میں قراءت کرتے تو سننے کا شوق رکھنے والے محروم رہ جاتے۔ اس پر اللہ عز وجل نے یہ آیت نازل فرمائی: ﴿ وَلَا تَجۡهَرۡ بِصَلَاتِكَ وَلَا تُخَافِتۡ بِهَا ﴾ [الإسراء: 110]","",{"k":"المعجم الأوسط للطبراني (2/16)"}],[368,"سیدہ عائشہ رضی اللہ عنہا سورۃ الاسراء کی اس آیت کا شانِ نزول بیان کرتے ہوئے فرماتی ہیں: ’’مشرکین نے آپ صلی اللہ علیہ وسلم کی آواز سنی تو آپ صلی اللہ علیہ وسلم کے پاس آئے اور برا بھلا کہنے لگے۔ اس پر اللہ تعالیٰ نے یہ آیت نازل فرمائی:\n﴿ قُلِ ٱدۡعُواْ ٱللَّهَ أَوِ ٱدۡعُواْ ٱلرَّحۡمَٰنَۖ أَيًّا مَّا تَدۡعُواْ فَلَهُ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰۚ وَلَا تَجۡهَرۡ بِصَلَاتِكَ وَلَا تُخَافِتۡ بِهَا وَٱبۡتَغِ بَيۡنَ ذَٰلِكَ سَبِيلًا ﴾ [الإسراء: 110]\n’’کہہ دیجیے: اللہ کو پکارو، یا رحمان کو پکارو، تم جس کو بھی پکارو گے سو یہ بہترین نام اسی کے ہیں اور اپنی نماز نہ بلند آواز سے پڑھو اور نہ اسے پست کرو اور اس کے درمیان کا راستہ اختیار کرو۔‘‘","",{"k":"تفسیر ابن جریر (15/183)۔ صحیح البخاري (7526)۔ صحیح مسلم (447)"}],[369,"سیدہ عائشہ رضی اللہ عنہا بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم بیت اللہ کے پاس اونچی آواز سے دعاء کررہے تھے: ’’یا اللہ! یا رحمن!‘‘ جب مکہ والوں نے سنا تو بھاگے آئے۔ اس پر اللہ عز وجل نے مذکورہ بالا آیت نازل فرمائی۔","",{"k":"الدر المنثور (4/373)۔ فتح الباري (13/360)"}],[370,"سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں: ’’میں نے جب سے ہوش سنبھالا تو اپنے ماں باپ کو مسلمان ہی پایا اور ہم پر کوئی دن ایسا نہیں گزرا جس میں رسول اللہ صلی اللہ علیہ وسلم صبح و شام دن کے دونوں وقت ہمارے گھر تشریف نہ لائے ہوں۔‘‘ پھر انہوں نے مکمل واقعہ بیان کیا۔ اس میں یہ بھی ذکر کیا کہ قریش نے ابن دَغِنہ کی پناہ کو رد نہ کیا اور کہا: ’’ابو بکر سے کہو کہ اپنے گھر میں اپنے رب کی عبادت کرے اور جو چاہے، پڑھتا رہے، لیکن ہمیں تکلیف نہ دے اور نہ اونچی آواز سے پڑھے۔‘‘","",{"k":"صحیح البخاري (476، 2264، 3905)"}],[371,"کُرَیب مولیٰ ابن عباس رحمہ اللہ (المتوفیٰ: 198ھ)بتاتے ہیں کہ میں نے ابن عباس رضی اللہ عنہ سے پوچھا: ’’رسول اللہ صلی اللہ علیہ وسلم کا قیام اللیل کیسا ہوتا تھا؟‘‘ انہوں نے فرمایا: ’’رسول اللہ صلی اللہ علیہ وسلم اپنے کسی حجرے میں قیام فرماتے اور اتنی اونچی آواز سے قراءت کرتے کہ باہر کھڑےبندے کو آوازآتی تھی۔‘‘","",{"k":"صحیح ابن خزیمۃ (1157)۔ صحیح ابن حبان (6/318)۔ السنن الکبری للبیھقي (3/11)"}],[372,"عبد اللہ بن ابی قیس رحمہ اللہ بیان کرتے ہیں کہ میں نے سیدہ عائشہ صدیقہ رضی اللہ عنہا سے رسول اللہ صلی اللہ علیہ وسلم کے وتر کے متعلق دریافت کرتے ہوئے پوچھا: ’’آپ صلی اللہ علیہ وسلم کی قراءت کیسی ہوتی تھی؟ اونچی آواز سے قرآن کی تلاوت کرتے تھے یا آہستہ آواز سے؟‘‘ انہوں نے جواب دیا: ’’بسا اوقات آپ صلی اللہ علیہ وسلم اونچی آواز سے قراءت کرتے تھے اور کبھی آہستہ آواز سے۔‘‘","",{"k":"صحیح مسلم (307)۔ سنن أبي داود (1437)۔ سنن الترمذي (499)"}],[373,"سیدنا عبد اللہ بن عباس رضی اللہ عنہ نے آیت کریمہ:\n﴿ لَا تُحَرِّكۡ بِهِۦ لِسَانَكَ لِتَعۡجَلَ بِهِۦٓ ﴾ [القیامۃ: 16]\n’’ (اے نبی!) اس وحی کو جلدی جلدی یاد کرلینے کے لیے اپنی زبان کو حرکت نہ دیجیے۔‘‘\nکی تفسیر کرتے ہوئے فرمایا: ’’رسول اللہ صلی اللہ علیہ وسلم نزول قرآن کے وقت بہت سختی محسوس فرمایا کرتے تھے اور اس (کی علامتوں) میں سے (ایک یہ) تھی کہ یاد کرنے کے لیے آپ اپنے ہونٹوں کو ہلاتے تھے۔ ابن عباس رضی اللہ عنہ نے کہا: ’’میں اپنے ہونٹ اس طرح ہلاتا ہوں جس طرح آپ صلی اللہ علیہ وسلم ہلاتے تھے۔‘‘ سعید (راوی حدیث) کہتے ہیں: میں بھی اس طرح اپنے ہونٹ ہلاتا ہوں جس طرح میں نے ابن عباس رضی اللہ عنہ کو ہونٹ ہلاتے دیکھا۔‘‘ پھر انہوں نے اپنے ہونٹ ہلائے۔ (ابن عباس رضی اللہ عنہ نے کہا:) پھر اللہ تعالیٰ نے یہ آیت نازل فرمائی:\n﴿ لَا تُحَرِّكۡ بِهِۦ لِسَانَكَ لِتَعۡجَلَ بِهِۦٓ ١٦ إِنَّ عَلَيۡنَا جَمۡعَهُۥ وَقُرۡءَانَهُۥ ﴾ [القیامۃ: 16–17]\n’’اے محمد! قرآن کو جلد جلد یاد کرنے کے لیے اپنی زبان نہ ہلاؤ۔ اس کا جمع کر دینا اور پڑھا دینا ہمارا ذمہ ہے۔‘‘\nابن عباس رضی اللہ عنہ کہتے ہیں: ’’یعنی قرآن آپ صلی اللہ علیہ وسلم کے سینے میں جما دینا اور پڑھا دینا ہمارے ذمہ ہے۔ ‘‘\n﴿ فَإِذَا قَرَأۡنَٰهُ فَٱتَّبِعۡ قُرۡءَانَهُۥ ﴾ [القیامۃ: 18]\n’’پھر جب ہم پڑھ چکیں تو اس پڑھے ہوئے کی اتباع کرو۔‘‘\nابن عباس رضی اللہ عنہ فرماتے ہیں: ’’(اس کا مطلب یہ ہے) کہ آپ خاموش رہ کر اس کو غور سے سنتے رہیں۔‘‘\n﴿ ثُمَّ إِنَّ عَلَيۡنَا بَيَانَهُۥ ﴾ [القیامۃ: 19]\n’’اس کے بعد مطلب سمجھا دینا ہمارے ذمہ ہے۔‘‘\nپھر یقیناً یہ ہماری ذمہ داری ہے کہ آپ اس کو پڑھیں (یعنی اس کو محفوظ کر سکیں) چنانچہ اس کے بعد جب آپ کے پاس جبرائیل علیہ السلام (وحی لے کر) آتے تو آپ صلی اللہ علیہ وسلم (توجہ سے) سنتے۔ جب وہ چلے جاتے تو رسول اللہ صلی اللہ علیہ وسلم اس (وحی) کو اسی طرح پڑھتے جس طرح جبرائیل علیہ السلام نے اسے پڑھا تھا۔‘‘","",{"k":"صحیح البخاري (5، 7524)۔ صحیح مسلم (448)"}],[374,"قتیبہ بن سعید از ابو عوانہ وجریر از موسیٰ بن ابی عائشہ از سعید بن جُبَیْر از ابن عباس کی سند سے بھی یہ تفسیر منقول ہے۔"],[375,"موسیٰ بن ابی عائشہ کہتے ہیں کہ انہوں نے سعید بن جبیر رحمہ اللہ سے آیت کریمہ: ﴿ لَا تُحَرِّكۡ بِهِۦ لِسَانَكَ لِتَعۡجَلَ بِهِۦٓ ﴾ [القیامۃ: 16] کی تفسیر پوچھی تو انہوں نے بتایا کہ ابن عباس رضی اللہ عنہ نے فرمایا تھا: ’’رسول اللہ صلی اللہ علیہ وسلم پر جب وحی نازل ہوتی تھی تو آپ صلی اللہ علیہ وسلم اپنے لب ہائے مبارک کو حرکت دیا کرتے تھے۔ آپ صلی اللہ علیہ وسلم سے کہا گیا: ’’آپ صلی اللہ علیہ وسلم ڈرتے ہیں کہ کہیں کچھ رہ نہ جائے؟ پھر\n﴿ إِنَّ عَلَيۡنَا جَمۡعَهُۥ ﴾ [القیامۃ: 17]\n’’اسے جمع کرنا ہماری ذمہ داری ہے۔‘‘\nپھر اسے ہم آپ صلی اللہ علیہ وسلم کے سینے میں محفوظ کریں گے۔\n﴿ وَقُرۡءَانَهُۥ ١٧ فَإِذَا قَرَأۡنَٰهُ ﴾ [القیامۃ: 17–18]\n’’اور اسے پڑھانا بھی۔ تو جب ہم اسے پڑھ چکیں۔‘‘\nابن عباس رضی اللہ عنہ فرماتے ہیں: آپ صلی اللہ علیہ وسلم پر یہ حکم نازل ہوا:\n﴿ فَٱتَّبِعۡ قُرۡءَانَهُۥ ١٨ ثُمَّ إِنَّ عَلَيۡنَا بَيَانَهُۥ ﴾ [القیامۃ: 18–19]\n’’آپ اس کی قراءت کی پیروی کیجیے۔ پھر اسے بیان کرنا ہماری ذمہ داری ہے۔‘‘\nیعنی اسے آپ صلی اللہ علیہ وسلم کی زبان سے ہم بیان کروائیں گے۔‘‘","",{"k":"صحیح البخاري (4928)"}],[376,"سیدنا عبد اللہ بن عباس رضی اللہ عنہ فرماتے ہیں کہ جب نبی کریم صلی اللہ علیہ وسلم پر وحی نازل ہوتی تو آپ صلی اللہ علیہ وسلم اپنی زبانِ مبارک کو حرکت دیتے۔ سفیان رحمہ اللہ نے زبان کو حرکت دے کر سمجھایا۔ آپ صلی اللہ علیہ وسلم کا مقصد یہ ہوتا تھا کہ اسے فوراً یاد کرلیں۔ اس پر اللہ تعالیٰ نے مذکورہ بالا آیات نازل فرما دیں۔","",{"k":"مسند الحمیدي (527)۔ صحیح البخاري (4927)"}],[377,"سیدنا ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ جبریل علیہ السلام جب کوئی آیت مبارکہ لاتے تو آپ صلی اللہ علیہ وسلم اسے یاد کرنے کےلیے زبانِ مبارک کو حرکت دیتے۔ اس پر اللہ تعالیٰ نے مذکورہ بالا آیات نازل فرمائیں۔ ان میں سے آیت: ’’جب ہم اسے پڑھ لیں تو اس پڑھنے کی پیروی کریں۔‘‘ کی وضاحت کرتے ہوئے ابن عباس رضی اللہ عنہ فرماتے ہیں: یعنی جبریل علیہ السلام کے عمل کی پیروی کیجیے اور اسے سمجھنے کی کوشش کیجیے۔‘‘","",{"k":"تفسیر ابن جریر (29/190)"}],[378,"سیدنا عبد اللہ بن عمرو بن عاص رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے مجھے کہا: ’’سات دن میں قرآن مکمل کرو اور اسے جلدی جلدی نہ پڑھو۔‘‘","",{"k":"صحیح البخاري (5052)۔ صحیح مسلم (1159)"}],[379,"جُبَیْر بن مُطْعِم رضی اللہ عنہ بیان کرتے ہیں کہ میں نبی کریم صلی اللہ علیہ وسلم کی خدمت میں قیدیوں کا فدیہ لے کر حاضر ہوا اورعصر کے بعد مسجد نبوی میں سوگیا۔ اس وقت میں حالتِ شرک میں تھا۔ اللہ کی قسم! مجھے مغرب کی نماز میں رسول اللہ صلی اللہ علیہ وسلم کی سورۃ الطور کی قراءت نے ہی جگایا۔","",{"k":"صحیح البخاري (765، 3050)۔ صحیح مسلم (463)"}],[380,"امام بخاری رحمہ اللہ فرماتے ہیں: بلا شبہ نُعَیْم بن حمَّاد رحمہ اللہ نے واضح فرمایا ہے کہ رب تعالیٰ کا کلام مخلوق نہیں ہے، اور یقیناً عرب لوگ زندہ کو مردہ کی نسبت اس کے فعل کے ذریعہ ہی پہچانتے ہیں۔ جو کوئی فعل سرانجام دیتا ہے، وہ زندہ ہے اور جو کوئی کام نہیں کرسکتا، وہ مردہ ہے۔ ان کا یہ بھی موقف تھا کہ بندوں کے افعال مخلوق ہیں۔ اسی وجہ سے انہیں تکالیف کا سامنا کرنا پڑنا، حتیٰ کہ دنیا سے رخصت ہوگئے۔ ان پر گزرنے والے تکلیف دہ حالات کی وجہ سے اہل علم کو ان پر ترس آتا ہے۔ مسلمانوں کا اتفاق اس بات کی دلیل ہے کہ نعیم اور ان جیسا موقف اپنانے والے نہ تو مسلمانوں کی جماعت سے الگ ہیں اور نہ ہی بدعتی ہیں۔ بلکہ بدعتی اور جہالت کے سرغنے مسلمانوں کی جماعت سے الگ ہونے اور بدعت میں مبتلا ہونے کے زیادہ حق دار ہیں کیونکہ یہ ایسی مختلف آراء پر مشتمل فتوے جاری کرتے ہیں جن کی اللہ تعالیٰ نے اجازت نہیں دی۔"],[381,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ فرماتے ہیں: ’’یہ قرآن جو تمہارے سامنے موجود ہے، قریب ہے کہ تم سے چھین لیا جائے۔‘‘ اس قول کو بیان کرنے والے شدَّاد بن مَعْقِل رحمہ اللہ کہتے ہیں کہ میں نے کہا: ’’عبد اللہ بن مسعود! ایسا کیسے ہوسکتا ہے جبکہ اللہ تعالیٰ نے اسے ہمارے دلوں میں نقش کردیا ہے اور ہم نے اسے مصاحف میں لکھ لیا ہے؟‘‘ انہوں نے فرمایا: ’’ایک ہی رات میں جو کچھ دلوں میں ہے، چھین لیا جائے اور جو کچھ مصاحف میں ہے، مٹ جائے گا۔‘‘ پھر انہوں نے اس آیت کریمہ کی تلاوت فرمائی:\n﴿ وَلَئِن شِئۡنَا لَنَذۡهَبَنَّ بِٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ ﴾ [الإسراء: 86]\n’’اور اگر ہم چاہیں تو جو کچھ وحی ہم نے تمہارے پاس بھیجی ہے، وہ ساری واپس لے جائیں۔‘‘","",{"k":"سنن سعید بن منصور (2/335)۔ مصنف عبد الرزاق (3/362، 363)۔ مصنف ابن أبي شیبۃ (10/534 – 535)"}],[382,"حُمَیدی از سفیان از عبد العزیز کی سند سے بھی یہ اثر منقول ہے۔","",{"k":"سنن سعید بن منصور (2/335)۔ الفتن لنعیم بن حماد (2/599، 603)۔ المستدرك للحاکم (4/504)"}],[383,"سفیان رحمہ اللہ آیت کریمہ:\n﴿ ثُمَّ لَا تَجِدُ لَكَ بِهِۦ عَلَيۡنَا وَكِيلًا ﴾ [الإسراء: 86]\n’’پھر آپ کو اس کے لئے ہمارے مقابلے میں کوئی حمایتی میسر نہ آسکے گا۔‘‘\nکی تفسیر کرتے ہوئے فرماتے ہیں: ’’آپ کو کوئی ایسا نہ ملے گا جو اس بات کی ضمانت دے کہ ہم اسے (یعنی آپ صلی اللہ علیہ وسلم پر نازل کردہ وحی کو) ختم نہیں کریں گے۔‘‘"],[384,"سیدنا عبد اللہ بن عمرو بن عاص رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’بلاشبہ اللہ تعالیٰ علم کو لوگوں کے سینوں سے نہیں کھینچے گا۔ بلکہ وہ علماء کو قبض کرکے علم لے جائے گا۔ یہاں تک کہ کسی عالم کو باقی نہ چھوڑے گا۔ پھر لوگ جہلاء کو اپنا سردار بنالیں گے اور ان سے مسائل کا حل دریافت کریں گے۔ وہ جاہل بغیر علم کے فتوے جھاڑیں گے جس کی وجہ سے خود بھی گمراہ ہوں گے اور دوسروں کو بھی گمراہ کریں گے۔‘‘","",{"k":"صحیح البخاري (100، 7307)۔ صحیح مسلم (2673)"}],[385,"سیدنا عِیَاض بن حمار رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ تعالیٰ نے مجھے وحی کے ذریعہ بتایا ہے کہ میں تجھ پر ایسی کتاب نازل کروں گا کہ جسے پانی دھو نہیں سکے گا۔ تم اسے سوتے جاگتے ہر حالت میں پڑھ سکو گے۔‘‘","",{"k":"صحیح مسلم (2865)"}],[386,"یہ بات بالکل ثابت شدہ ہے کہ عثمان رضی اللہ عنہ نے زید بن ثابت رضی اللہ عنہ کو مصاحف کے نسخے تیار کرنے کا حکم دیا اور پھر دیگر تمام مصاحف کو جلا دیا۔"],[387,"یہ بات ابو الیمان از شعیب از زہری از انس از عثمان کی سند سے مروی ہے۔","",{"k":"صحیح البخاري (4987)۔ المصاحف لابن أبي داود (ص 26 – 27)"}],[388,"مُصْعب بن سعد رحمہ اللہ فرماتے ہیں کہ جب عثمان رضی اللہ عنہ نے مصاحف کو پھاڑا تو میں نے صحابہ کرام کو دیکھا کہ انہیں یہ عمل پسند آیا، یا انہوں نے کہا کہ کسی صحابی نے اس پر اعتراض نہیں کیا اور عثمان رضی اللہ عنہ کو قرآن جلانے والا نہیں کہا جائے گا۔","",{"k":"المصاحف لابن أبي داود (ص 19، 31 – 32)"}],[389,"قرآن کو جلانے والی بات محمد بن مثنی از عبد الرحمن از انس از عثمان کی سند سے بھی مروی ہے۔","",{"k":"سنن الترمذي (3103–3104)۔ المصاحف لابن أبي داود، ص: 25 – 26۔ اصل سند میں عبد الرحمن بن مہدی اور انس کے درمیان دو واسطے ہیں۔ یعنی عبد الرحمن بن مہدی از ابراہیم بن سعد از زہری ازٍ انس ہے۔"}],[390,"سعد بن ہشام رحمہ اللہ کہتے ہیں کہ میں نے عائشہ رضی اللہ عنہا سے رسول اللہ صلی اللہ علیہ وسلم کے اخلاق کے بارے میں دریافت کیا تو انہوں نے فرمایا: ’’آپ صلی اللہ علیہ وسلم کا اخلاق قرآن ہی تو تھا۔‘‘","",{"k":"صحیح مسلم (746)۔ المعجم الأوسط للطبراني (1/30)"}],[391,"سیدنا ابو امامہ باہلی رضی اللہ عنہ فرماتے ہیں: ’’قرآن پڑھا کرو۔ یہ لٹکے ہوئے مصاحف تمہیں دھوکے میں نہ ڈالیں کیونکہ جس دل میں قرآن محفوظ ہوگا، اللہ تعالیٰ اسے عذاب نہیں دیں گے۔‘‘","",{"k":"سنن الدارمي (3320)۔ مصنف ابن أبي شیبۃ (10/505)۔ الزھد لابن أبي عاصم (ص 204)"}],[392,"سیدنا عبد اللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے دشمن کی سرزمین میں قرآن لے جانے سے منع فرمایا ہے۔","",{"k":"مؤطا مالك (2/446)۔ صحیح البخاري (2990)۔ صحیح مسلم (1869)"}],[393,"سیدنا عبد اللہ بن عمر رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے دشمن کے علاقے میں مصحف لے جانے سے روکا ہے۔","",{"k":"مسند أحمد (2/76)۔ المصاحف لابن أبي داود (ص 206)"}],[394,"امام بخاری رحمہ اللہ فرماتے ہیں: اس روایت کو بیان کرنے میں محمد بن بشر نے احمد بن خالد (پچھلی روایت کے راوی) کی متابعت کی ہے۔ انہوں نے عبید اللہ سے، انہوں نے نافع سے اور انہوں نے ابن عمر رضی اللہ عنہ کے حوالہ سے نبی کریم صلی اللہ علیہ وسلم سے یہی حکم روایت کیا ہے۔ ظاہر ہے کہ دشمن کی سرزمین میں مخلوق (یعنی لکھے ہوئے قرآن کی جلد)ہی لے جائی جاسکتی ہے۔"],[395,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ فرماتے ہیں: ’’میں نے کچھ قراء کو پڑھتے ہوئے سنا ہے۔ میرے مطابق وہ قریب قریب ایک جیسا ہی پڑھ رہے تھے۔تو جیسا تمہیں سکھایا گیا ہے، ویسے ہی پڑھو۔‘‘ ابن عباس رضی اللہ عنہ کا قول ہے: ’’تم کس قراءت کو اولین قراءت سمجھتے ہو؟‘‘","",{"k":"تفسیر عبد الرزاق (2/320)۔ تفسیر ابن جریر (1/22)۔ فضائل القرآن لأبي عبید (753، 797)"}],[396,"سیدنا عبد اللہ بن عباس رضی اللہ عنہ نے ایک مرتبہ سوال کیا کہ تم کس قراءت کو اولین قراءت سمجھتے ہو؟ سامعین کہتے ہیں کہ ہم نے کہا: ’’عبد اللہ بن مسعود رضی اللہ عنہ کی قراءت کو۔‘‘ تو انہوں نے فرمایا: ’’نہیں، دراصل رسول اللہ صلی اللہ علیہ وسلم ہر رمضان میں قرآن کا ایک مرتبہ دور کرتے تھے جبکہ اپنی زندگی کے آخری رمضان میں دو مرتبہ دور کیا۔ اس وقت عبد اللہ بن مسعود رضی اللہ عنہ آپ صلی اللہ علیہ وسلم کے پاس گئے تو انہوں نے گواہی دی کہ قرآن میں کیا کچھ منسوخ ہوگیا ہے اور کیا کچھ بدل دیا گیا ہے۔‘‘","",{"k":"السنن الکبری للنسائي (7994/3)۔ مسند أحمد (1/362)۔ سنن سعید بن منصور (1/240)"}],[397,"اس قول کو زائدہ اور یعلیٰ نے بھی اعمش سے روایت کیا ہے۔","",{"k":"مسند أحمد (1/362)"}],[398,"مُرَّہ بن شراحیل ہمدانی رحمہ اللہ بیان کرتے ہیں کہ میں عبد اللہ بن مسعود رضی اللہ عنہ کی تلاش میں ان کے گھر گیا تو معلوم ہوا کہ وہ ابو موسیٰ رضی اللہ عنہ کے پاس ہیں۔ چنانچہ میں ابو موسیٰ رضی اللہ عنہ کے پاس چلا گیا۔ وہاں گیا تو عبد اللہ بن مسعود رضی اللہ عنہ کے ساتھ ساتھ حذیفہ رضی اللہ عنہ سے بھی ملاقات ہوگئی۔ عبد اللہ بن مسعود رضی اللہ عنہ حذیفہ رضی اللہ عنہ سے کہہ رہے تھے: ’’آپ حدیث والے ہیں۔‘‘ حذیفہ نے کہا: ’’جی ہاں، مجھے لوگوں کا یہ کہنا: ’’یہ فلاں کی قراءت ہے اور یہ فلاں کی قراءت ہے‘‘ناپسند ہے۔","",{"k":"المصاحف لابن أبي داود (ص 20)"}],[399,"مذکورہ اثر میں حذیفہ رضی اللہ عنہ نے واضح فرما دیا کہ قرآن اور قاری میں فرق ہے۔امام بخاری رحمہ اللہ فرماتے ہیں: یہ بات درج ذیل روایت سے بھی واضح ہوتی ہے:"],[400,"قاری عبیداللہ بن عیاض رحمہ اللہ کہتے ہیں کہ عبداللہ بن شداد رضی اللہ عنہ عائشہ صدیقہ رضی اللہ عنہا کی خدمت میں حاضر ہوئے، اس وقت ہم لوگ عائشہ رضی اللہ عنہا کے پاس ہی بیٹھے ہوئے تھے۔عبد اللہ بن شداد رضی اللہ عنہ نے کہا: ’’جب علی رضی اللہ عنہ کو جب یہ بات معلوم ہوئی کہ لوگ ان پر کیا اعتراض کررہے ہیں اور کس وجہ سے ان سے ناراض ہو کر جدا ہوگئے ہیں تو انہوں نے منادی کو یہ ندا لگانے کا حکم دیا کہ امیرالمومنین کے پاس صرف وہی شخص آئے جس نے قرآن کریم اٹھا رکھا ہو۔ جب ان کا گھر قرآن پڑھنے والوں سے بھر گیا تو انہوں نے قرآن کریم کا ایک بڑا نسخہ منگوا کر اپنے سامنے رکھا اور اسے اپنے ہاتھ سے ہلاتے ہوئے کہنے لگے: ’’اے قرآن! لوگوں کو بتاؤ، لوگوں کو آگاہ کرو۔‘‘ یہ دیکھ کر لوگ کہنے لگے: ’’امیرالمومنین! آپ اس نسخے سے کیا پوچھ رہے ہیں؟ یہ تو کاغذ پر روشنائی ہے۔ ہم تو وہی بات کرتے ہیں جو اس میں دیکھتے ہیں۔ آپ کہنا کیا چاہتے ہیں؟‘‘ فرمایا: ’’تمہارے وہ ساتھی جو ہم سے جدا ہو کر چلے گئے ہیں، میرے اور ان کے درمیان قرآن کریم ہی فیصلہ کرے گا، اللہ تعالیٰ خود قرآن کریم میں میاں بیوی کے حوالے سے فرماتے ہیں:\n﴿ وَإِنۡ خِفۡتُمۡ شِقَاقَ بَيۡنِهِمَا فَٱبۡعَثُواْ حَكَمًا مِّنۡ أَهۡلِهِۦ وَحَكَمًا مِّنۡ أَهۡلِهَآ إِن يُرِيدَآ إِصۡلَٰحًا يُوَفِّقِ ٱللَّهُ بَيۡنَهُمَآۗ ﴾ [النساء: 35]\n’’اگر تمہیں ان دونوں کے درمیان ناچاقی کا اندیشہ ہو تو ایک ثالث مرد کی طرف سے اور ایک ثالث عورت کے اہل خانہ کی طرف سے بھیجو، اگر ان کی نیت محض اصلاح کی ہوئی تو اللہ ان دونوں کے درمیان موافقت پیدا فرما دے گا۔‘‘\nمیرا خیال ہے کہ ایک آدمی اور ایک عورت کی نسبت پوری امت کا خون اور حرمت زیادہ اہم ہے (اس لیے اگر میں نے اس معاملہ میں ثالثی کو قبول کیا تو کونسا گناہ کیا؟) پھر انہوں نے پوری حدیث بیان کی۔ آخر میں سیدہ عائشہ رضی اللہ عنہا نے فرمایا: ’’علی رضی اللہ عنہ نے بالکل سچ کہا ہے، جبکہ اہل عراق ان کی طرف جھوٹی باتیں منسوب کرنا شروع کردیتے ہیں اور اپنی طرف سے رائی کا پہاڑ بنا دیتے ہیں۔‘‘","",{"k":"مسند أحمد (1/86 – 87)۔ مسند أبي یعلیٰ (474)"}],[401,"شقیق بیان کرتے ہیں کہ عبد اللہ بن مسعود رضی اللہ عنہ نے سونے سے مزین ایک مصحف دیکھا تو فرمایا: ’’مصحف کو مزین کرنے کےلیے بہتر یہ ہے کہ اس کی تلاوت کا حق ادا کیا جائے۔‘‘","",{"k":"فضائل القرآن لأبي عبید (906)۔ مصنف عبد الرزاق (4/323)۔ المصاحف لابن أبي داود (ص 168)"}],[402,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ کا فرمان ہے: ’’مصحف کو مزین کرنے والی سب سے اچھی چیز اس کی تلاوت کا حق ادا کرنا ہے۔‘‘","",{"k":"سنن سعید بن منصور (2/485)۔ مصنف ابن أبي شیبۃ (10/546)۔ المصاحف لابن أبي داود (ص 168)"}],[403,"ابن جُبَیْر کہتے ہیں کہ ابو جُمْعہ انصاری رضی اللہ عنہ ہمارے یہاں تشریف لائے تو انہوں نے فرمایا: ’’ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے اور ہمارے ساتھ دسویں آدمی معاذ بن جبل رضی اللہ عنہ تھے۔ ہم نے کہا: ’’یا رسول اللہ! ہم سے زیادہ بھی کوئی اجر کا مستحق ہوگا؟ کیونکہ ہم آپ صلی اللہ علیہ وسلم پر ایمان لائے ہیں اور آپ صلی اللہ علیہ وسلم کی پیروی کررہے ہیں۔‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’تمہیں ایمان لانے اور میری پیروی کرنے سے کیا چیز روک سکتی ہے جبکہ اللہ کا رسول تمہارے اندر موجود ہےاور تمہارے پاس آسمان سے تازہ بتازہ وحی آرہی ہے۔جبکہ وہ لوگ، جو تمہارے بعد آئیں گے، وہ دو تختیوں میں اس کتاب کو دیکھیں گے تو اس پر ایمان لائیں گے اور اس کی تعلیمات پر عمل پیرا ہوں گے، وہ لوگ اجر میں تم سے بہت آگے ہوں گے۔ وہ لوگ اجر کے اعتبار سے تم سے بہت آگے ہوں گے۔‘‘","",{"k":"مسند الرویاني (2/512)۔ الآحاد والمثاني لابن أبي عاصم (4/152)۔ المعجم الکبیر للطبراني (4/23)"}],[404,"سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں: ’’جو بندہ یہ سمجھتا ہے کہ محمد صلی اللہ علیہ وسلم نے وحی کا کوئی حصہ چھپا لیا تھا تو یقیناً وہ بندہ اللہ پر بہت بڑا جھوٹ باندھتا ہے، جبکہ اللہ تعالیٰ کا فرمان ہے:\n﴿ يَٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغۡ مَآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَۖ وَإِن لَّمۡ تَفۡعَلۡ فَمَا بَلَّغۡتَ رِسَالَتَهُۥۚ ﴾ [المائدۃ: 67]\n’’اے رسول! جو کچھ آپ کے پروردگار کی طرف سے آپ پر نازل کیا گیا ہے اسے لوگوں تک پہنچا دیجیے۔ اور اگر آپ نے ایسا نہ کیا تو اللہ کا پیغام پہنچانے کا حق ادا نہ کیا۔‘‘","",{"k":"صحیح البخاري (7531)۔ صحیح مسلم (177)"}],[405,"صالح علیہ السلام نے فرمایا:\n﴿ يَٰقَوۡمِ لَقَدۡ أَبۡلَغۡتُكُمۡ رِسَالَةَ رَبِّي ﴾ [الأعراف: 79]\n’’اے میری قوم! میں نے تمہیں اپنے رب کا پیغام پہنچا دیا تھا۔‘‘\nشعیب علیہ السلام نے فرمایا:\n﴿ لَقَدۡ أَبۡلَغۡتُكُمۡ رِسَٰلَٰتِ رَبِّي ﴾ [الأعراف: 79]\n’’یقیناً میں نے تمھیں اپنے رب کے پیغامات پہنچا دیے۔‘‘\nاور اللہ تعالیٰ کا فرمان ہے:\n﴿ لِّيَعۡلَمَ أَن قَدۡ أَبۡلَغُواْ رِسَٰلَٰتِ رَبِّهِمۡ ﴾ [الجن: 28]\n’’تاکہ اللہ جان لے کہ انہوں نے اپنے پروردگار کے پیغامات پہنچا دیے ہیں۔‘‘"],[406,"ان آیات کے ذریعہ اللہ تعالیٰ نے واضح فرما دیا کہ پیغام اللہ کی طرف سے آتا ہے اور اس کی تبلیغ رسولوں کی طرف سے ہوتی ہے۔"],[407,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ ایک دن یہودی رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور دروازے پر بیٹھ کر اندر آنے کی اجازت طلب کرنے لگے۔ رسول اللہ صلی اللہ علیہ وسلم نے فارغ ہوکر انہیں اندر بلایا تو انہوں نے کہا: ’’ابو القاسم! آج آپ نے ایسا کام کیا ہے جو آپ کی عادت نہیں ہے۔ آپ نے ہمیں دروازے پر روکے رکھا۔‘‘ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میرے رب نے مجھے ایسا کرنے کا حکم دیا تھا۔ اس نے مجھ پر یہ یہ وحی نازل کی ہے۔‘‘ یہود نے کہا: ’’اس ذات کی قسم جس نے موسیٰ علیہ السلام پر تورات نازل کی تھی! ہم تو دیکھ رہے ہیں کہ آپ کی امت ساری امتوں سے زیادہ جلدی اپنے نبی کی بات مانتی ہے۔ قریب ہے کہ یہ باقی امتوں سے زیادہ جلدی اپنے دین سے پھر جائے۔‘‘","",{"k":"التاریخ الکبیر للبخاري (5/164)"}],[408,"سیدنا عبد اللہ بن عباس رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے یوم النحر کو خطبہ دیا تو اس میں فرمایا: ’’لوگو! یہ کون سا دن ہے؟‘‘ صحابہ نے عرض کیا: ’’احترام والا دن ہے۔‘‘ پوچھا: ’’شہر کون سا ہے؟‘‘ کہا: ’’محترم شہر ہے۔‘‘ پوچھا: ’’مہینہ کون سا ہے؟‘‘ جواب دیا: ’’حرمت والا مہینہ ہے۔‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’جس طرح یہ دن اس مہینہ میں اور یہ مہینہ اس شہر میں احترام کے لائق ہے، اسی طرح تمہاریں جانیں اور تمہارے اموال بھی ایک دوسرے کےلیے قابلِ احترام ہیں۔‘‘ آپ صلی اللہ علیہ وسلم نے یہ بات تین مرتبہ دہرائی، پھر آسمان کی طرف سر اٹھا کر فرمایا: ’’اے اللہ! کیا میں نے تیرا پیغام پہنچا دیا؟‘‘ ابن عباس رضی اللہ عنہ فرماتے ہیں: ’’اس ذات کی قسم جس کے ہاتھ میں میری جان ہے، یقیناً آپ صلی اللہ علیہ وسلم نے اپنی امت کو وصیت فرمائی تھی کہ ’’جو لوگ یہاں موجود ہیں، وہ غیر حاضر لوگوں تک یہ باتیں پہنچا دیں اور یہ کہ میرے بعد کافر بن کر ایک دوسرے کی گردنیں نہ کاٹنا۔‘‘","",{"k":"صحیح البخاري (1739، 7079)"}],[409,"ابوشریح رضی اللہ عنہ بیان کرتے ہیں کہ انہوں نے عمرو بن سعید (والی مدینہ) سے، جب وہ مکہ میں فوجیں بھیج رہا تھا، کہا: ’’اے امیر! آپ مجھے اجازت دیں تو میں وہ حدیث آپ سے بیان کر دوں جو رسول اللہ صلی اللہ علیہ وسلم نے فتح مکہ کے دوسرے دن ارشاد فرمائی تھی، اس (حدیث) کو میرے دونوں کانوں نے سنا تھا اور میرے دل نے اسے یاد رکھا ہے اور جب رسول اللہ صلی اللہ علیہ وسلم یہ حدیث ارشاد فرما رہے تھے تو میری آنکھیں آپ صلی اللہ علیہ وسلم کو دیکھ رہی تھیں۔ آپ صلی اللہ علیہ وسلم نے (پہلے) اللہ کی حمد و ثنا بیان کی، پھر فرمایا: ’’مکہ کو اللہ نے حرام کیا ہے، آدمیوں نے حرام نہیں کیا۔ تو (سن لو) کہ کسی شخص کے لیے جو اللہ پر اور یوم آخرت پر ایمان رکھتا ہو، جائز نہیں ہے کہ مکہ میں خون ریزی کرے، یا اس کا کوئی درخت کاٹے۔ پھر اگر کوئی اللہ کے رسول صلی اللہ علیہ وسلم (کے لڑنے) کی وجہ سے اس کا جواز نکالے تو اس سے کہہ دو: ’’اللہ نے اپنے رسول صلی اللہ علیہ وسلم کو خصوصی اجازت دی تھی جو تمہیں نہیں دی اور مجھے بھی دن کے کچھ لمحوں کے لیے اجازت ملی تھی۔ پھر آج اس کی حرمت لوٹ آئی، جیسی کل تھی۔ اور حاضر غائب تک (یہ بات) پہنچا دے۔‘‘","",{"k":"صحیح البخاري (104)۔ صحیح مسلم (1354)"}],[410,"سیدنا ابوبکرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے (ذو الحجہ کی) دسویں تاریخ کو منیٰ میں خطبہ دیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’لوگو! معلوم ہے آج کون سا دن ہے؟‘‘ ہم نے عرض کی: ’’اللہ اور اس کا رسول زیادہ جانتے ہیں۔‘‘ آپ صلی اللہ علیہ وسلم یہ سن کر خاموش ہو گئے اور ہم نے سمجھا کہ آپ صلی اللہ علیہ وسلم اس دن کا کوئی اور نام رکھیں گے لیکن آپ صلی اللہ علیہ وسلم نے فرمایا: ’’کیا یہ یوم النحر (قربانی کا دن) نہیں؟‘‘ ہم بولے: ’’جی بالکل۔‘‘ پھر آپ صلی اللہ علیہ وسلم نے پوچھا: ’’یہ مہینہ کون سا ہے؟‘‘ ہم نے کہا: ’’اللہ اور اس کے رسول زیادہ جانتے ہیں۔‘‘ آپ صلی اللہ علیہ وسلم اس مرتبہ بھی خاموش ہو گئے اور ہمیں خیال ہوا کہ آپ صلی اللہ علیہ وسلم اس مہینہ کا نام بدل کر کوئی اور رکھیں گے، لیکن آپ نے فرمایا: ’’کیا یہ ذو الحجہ کا مہینہ نہیں ہے؟‘‘ ہم بولے: ’’کیوں نہیں۔‘‘ پھر آپ صلی اللہ علیہ وسلم نے پوچھا: ’’یہ شہر کون سا ہے؟‘‘ ہم نے عرض کیا: ’’اللہ اور اس کے رسول بہتر جانتے ہیں۔‘‘ اس مرتبہ بھی آپ صلی اللہ علیہ وسلم اس طرح خاموش ہو گئے کہ ہم نے سمجھا کہ آپ صلی اللہ علیہ وسلم اس کا کوئی اور نام رکھیں گے، لیکن آپ صلی اللہ علیہ وسلم نے فرمایا: ’’کیا یہ حرمت والا شہر نہیں ہے؟‘‘ ہم نے عرض کیا: ’’کیوں نہیں، ضرور ہے۔‘‘ اس کے بعد آپ صلی اللہ علیہ وسلم نے ارشاد فرمایا: ’’بس تمہارا خون اور تمہارے مال ایک دوسرے پر اپنے رب سے ملاقات کے دن تک اسی طرح حرام ہیں جیسے اس دن کی حرمت اس مہینہ اور اس شہر میں ہے۔‘‘ بتاؤ: کیا میں نے تم تک اللہ کا پیغام پہنچا دیا؟‘‘ لوگوں نے کہا: ’’جی ہاں۔‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اے اللہ! تو گواہ رہنا اور ہاں! یہاں موجود افراد غیر حاضر لوگوں تک پہنچا دیں کیونکہ بہت سے لوگ جن تک یہ پیغام پہنچے گا، سننے والوں سے زیادہ (پیغام کو) یاد رکھنے والے ثابت ہوں گے اور میرے بعد کافر نہ بن جانا کہ ایک دوسرے کی (ناحق) گردنیں کاٹنے لگو۔‘‘","",{"k":"صحیح البخاري (1741)۔ صحیح مسلم (1679)"}],[411,"ایک اور سند سے بھی ابو بکرہ رضی اللہ عنہ سے یہ روایت مروی ہے۔ اس کے آخر میں یہ الفاظ ہیں: ’’یہاں موجود شخص پر لازم ہے کہ غیر حاضر تک یہ تمام باتیں پہنچا دے۔ بسا اوقات مبلغ اس تک بات پہنچا دیتا ہے جو اسے زیادہ اچھے طریقے سے یاد رکھتا ہے۔‘‘ تو ایسے ہی ہوا۔","",{"k":"صحیح البخاري (7078)"}],[412,"سرّاء بنت نبہان رضی اللہ عنہا بیان کرتی ہیں کہ میں نے نبی کریم صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ’’تم میں سے قریب تر پر لازم ہے کہ اپنے سے دور فرد تک بات پہنچا دے۔‘‘ آپ صلی اللہ علیہ وسلم نے تین مرتبہ یہ الفاظ ارشاد فرمائے۔","",{"k":"سنن أبي داود (1953)۔ صحیح ابن خزیمۃ (3792)۔ الآحاد والمثاني لابن أبي عاصم (6/92)"}],[413,"بنو عُقَیل کے فرد عبد الکریم بیان کرتے ہیں کہ جب یزید بن مُہَلَّب آئے تو میں ان کے ساتھ نکلا۔ جب ہمارا گزر زُجَیْج مقام سے ہوا تو وہاں ایک بزرگ شیخ فرما رہے تھے: ’’میں نے حجۃ الوداع میں نبی کریم صلی اللہ علیہ وسلم سے سنا، اس وقت میں آپ صلی اللہ علیہ وسلم کی اونٹنی کی گردن کے نیچے موجود تھا، آپ صلی اللہ علیہ وسلم فرما رہے تھے: ’’لوگو! جانتے ہو یہ کون سا مہینہ ہے؟ حرمت والا مہینہ ہے، قابلِ احترام شہر ہے اور محترم دن ہے۔ سنو! تمہاری جانیں، تمہارے مال اور تمہاری عزتیں رب سے ملاقات کے دن تک ایک دوسرے پر ایسے ہی حرام ہیں جیسے اس شہر اور اس مہینہ میں یہ دن قابلِ احترام ہے۔ یا اللہ! گواہ بن جا۔ الٰہی! گواہ رہنا۔ الٰہا! گواہ رہنا۔‘‘ تین مرتبہ فرمایا۔’’حاضر باش پر لازم ہے کہ غیر حاضر تک پہنچا دے۔‘‘ پھر معلوم ہوا کہ وہ بزرگ عدّاء بن خالد عامری تھے۔","",{"k":"مسند أحمد (5/30)۔ الآحاد والمثاني لابن أبي عاصم (1502)۔ مسند الرویاني (1507)"}],[414,"حارث ابن عمرو سہمی رضی اللہ عنہ بیان کرتے ہیں کہ میں نبی کریم صلی اللہ علیہ وسلم کے پاس گیا۔ پھر انہوں نے یہی واقعہ سنایا اور اس میں یہ الفاظ بھی بیان کیے: ’’یہاں موجود پر لازم ہے کہ غیر موجود تک پہنچا دیں۔‘‘","",{"k":"مسند أحمد (3/485)۔ طبقات ابن سعد (6/64)۔ الآحاد والمثاني لابن أبي عاصم (1257)"}],[415,"بہز بن حکیم کے دادا (سیدنا معاویہ بن حیدہ قشیری رضی اللہ عنہ) بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’تم میں سے حاضر اپنے غیر حاضرلوگوں تک پہنچادیں۔‘‘","",{"k":"سنن ابن ماجہ (234)۔ مسند أحمد (5/4)"}],[416,"صُنَّابِحِی بیان کرتے ہیں کہ ہم سیدنا عبادہ بن صامت رضی اللہ عنہ کے پاس ان کی بیماری کی حالت میں گئے توانہوں نے فرمایا: ’’جسے یہ پسند ہو کہ وہ ایسے شخص کو دیکھے کہ گویا اسے آسمان پر لے جایا گیا ہو اور پھر زمین پر اتارا گیا ہو اور ہر وہ عمل کرتا ہو جو اس نے (آسمانوں پر) دیکھا تو وہ اس بندے (صنابحی)کو دیکھ لے۔ اور اگر میں استطاعت رکھوں گا تو(اے صنابحی! تمہیں فائدہ پہنچاؤں گا)۔‘‘ پھر عبادہ رضی اللہ عنہ نے فرمایا: ’’میں نے رسول اللہ صلی اللہ علیہ وسلم سے جو بھی حدیث سنی تھی، جس میں تمہارے لیے کوئی خیر تھی تو وہ تمہارے سامنے بیان کردی تھی، سوائے درج ذیل حدیث کے، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا تھا: ’’تم میں سے حاضر آدمی غیر موجود تک یہ باتیں پہنچا دے۔ اور جو بندہ ’’لا الٰہ الا اللہ وحدہ لا شریك لہ‘‘ کی گواہی دیتے ہوئے دنیا سے رخصت ہو تو اس کےلیے جنت واجب ہوجاتی ہے۔‘‘","",{"k":"المعرفۃ والتاریخ للفسوي (2/359)۔ التاریخ الکبیر للبخاري (5/321)۔ صحیح مسلم (29)"}],[417,"سیدنا عبادہ بن صامت رضی اللہ عنہ فرماتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا تھا: ’’میں تمہیں ایک حدیث بیان کرنے لگا ہوں، تم میں سے ہرحاضر آدمی پر لازم ہے کہ غیر حاضر لوگوں تک اسے پہنچا دے۔‘‘","",{"k":"المعرفۃ والتاریخ للفسوي (2/360)"}],[418,"زہیر بن اقمر کہتے ہیں: جب علی رضی اللہ عنہ شہید ہوگئے اور سیدنا حسن رضی اللہ عنہ منبر پر چڑھے تو ایک آدمی نے کھڑے ہوکر کہا: ’’میں نے رسول اللہ صلی اللہ علیہ وسلم کو انہیں (یعنی حسن رضی اللہ عنہ کو) اپنی گود میں اٹھائے ہوئے دیکھا تھا۔ اس وقت آپ صلی اللہ علیہ وسلم فرما رہے تھے: ’’یا اللہ! مجھے اس سے محبت ہے، تو بھی اس سے پیار کر۔ جو حاضر ہے، اس پر لازم ہے کہ غیر حاضر تک یہ بات پہنچا دے۔‘‘ اگر رسول اللہ صلی اللہ علیہ وسلم نے لازمی قرار نہ دیا ہوتا تو میں یہ حدیث کبھی بھی تمہارے سامنے بیان نہ کرتا۔ پھر اس کے بعد میں نے آپ صلی اللہ علیہ وسلم کو گفتگو کرتے ہوئے سنا تو آپ صلی اللہ علیہ وسلم فرما رہے تھے: ’’جو مجھ سے محبت کرتا ہے، اس پر لازم ہے کہ اس (حسن رضی اللہ عنہ) سے بھی محبت کرے۔‘‘","",{"k":"مسند أحمد (5/366)"}],[419,"ایک اور سند سے بھی یہ روایت مروی ہے، اس میں یہ الفاظ ہیں کہ قبیلہ اسد کا ایک فرد کھڑا ہوا اور اس نے کہا کہ آپ صلی اللہ علیہ وسلم نے فرمایا تھا: ’’جو مجھ سے محبت رکھتا ہے، اس پر لازم ہے کہ اسے بھی محبوب رکھے۔‘‘"],[420,"سلیمان بن حبیب محاربی بیان کرتے ہیں کہ ہم حِمْص گئے تو ہمیں بتایا گیا کہ سیدنا ابو امامہ رضی اللہ عنہ یہاں موجود ہیں۔ ہم ان کے پاس حاضر ہوئے تو دیکھا کہ وہ اس مجلس میں موجود تمام لوگوں سے بوڑھے تھے۔ انہوں نے فرمایا: ’’یہ مجلس اللہ تعالیٰ کی طرف سے تم تک پیغام پہنچانے کا ذریعہ ہے۔‘‘ پھر انہوں نے کہا: ’’رسول اللہ صلی اللہ علیہ وسلم کو جو پیغام دیا گیا تھا، وہ انہوں نے پہنچا دیا ہے۔ اب تم لوگ ہم سے جو سنو، اسے آگے پہنچا دو۔‘‘","",{"k":"طبقات ابن سعد (7/411)۔ المعجم الکبیر للطبراني (8/118 – 119)"}],[421,"سیدنا مغیرہ بن شعبہ رضی اللہ عنہ نے کِسری کے گورنر کو مخاطب کرکے فرمایا: ’’ہمارے نبی صلی اللہ علیہ وسلم نے ہمیں ہمارے رب کا یہ پیغام پہنچایا ہے کہ ہم میں سے جو شہید ہوجائے گا، وہ جنت کی ایسی آسائشیں حاصل کرلے گا جو اس نے کبھی نہیں دیکھی ہوں گی، اور جو زندہ رہے گا، وہ تمہاری گردنوں کا مالک بن جائے گا۔‘‘","",{"k":"صحیح البخاري (3159، 7530)"}],[422,"سیدنا عبد اللہ بن عباس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میں تمہارے پاس تمہارے مال لینے یا تمہارے اندر کوئی مقام ومرتبہ حاصل کرنے کےلیے نہیں آیا، بلکہ اللہ تعالیٰ نے مجھے تمہاری طرف رسول بنا کر بھیجا ہے اور مجھ پر ایک کتاب نازل فرمائی ہے اور مجھے حکم دیا ہے کہ تمہیں خبردار بھی کروں اور خوشخبری بھی سناؤں۔ تو میں تمہیں اپنے رب کا پیغام دے چکا ہوں اور تمہاری خیر خواہی کررہا ہوں۔ اگر میرے لائے ہوئے پیغام کو تسلیم کرلو گے تو دنیا وآخرت میں فائدہ اٹھاؤ گے اور اگر اسے ٹھکراؤ گے تو میں اللہ کے حکم پر صبر کروں گا یہاں تک کہ وہ میرے اور تمہارے درمیان فیصلہ صادر کردے۔‘‘","",{"k":"تفسیر ابن جریر (15/164 – 166)"}],[423,"سیدنا عدی بن حاتم رضی اللہ عنہ بیان کرتے ہیں کہ ایک مرتبہ میں نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر تھا تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’تم میں سے ہر ایک اپنے رب سے ضرور ملاقات کرے گا اور اللہ تعالیٰ ضرور اس سے پوچھیں گے: ’’کیا میں نے تمہاری طرف کوئی رسول مبعوث نہیں کیا تھا جس نے تم تک میرا پیغام پہنچایا ہو؟‘‘","",{"k":"صحیح البخاري (3595)"}],[424,"ثعلبہ بن عِبَاد بصری بیان کرتے ہیں کہ انہوں نے سیدنا سَمُرہ بن جُنْدب رضی اللہ عنہ کا ایک خطاب سنا، اس میں وہ فرما رہے تھے: ’’ایک مرتبہ آپ صلی اللہ علیہ وسلم لوگوں کو نماز ِ کسوف (سورج گرہن کی نماز) پڑھانے کےلیے نکلے تو ہم نے بھی آپ صلی اللہ علیہ وسلم کے ساتھ پڑھی۔نماز کے بعد آپ صلی اللہ علیہ وسلم نے خطبہ دیتے ہوئے ارشاد فرمایا: ’’میں تو صرف ایک انسان اور (اللہ کا) رسول ہوں۔ میں تمہیں اللہ کا واسطہ دے کر پوچھتا ہوں کہ اگر تمہارے علم کے مطابق میں نے اپنے رب کے پیغامات پہنچانے میں کسی قسم کی کوئی کوتاہی برتی ہے (تو مجھے بتا دو۔‘‘) صحابہ نے عرض کیا: ’’ہم گواہی دیتے ہیں کہ آپ نے اپنے رب کے پیغامات پہنچا دیے ہیں اور اپنی ذمہ داری کو بطریقِ احسن پورا کیا ہے۔‘‘","",{"k":"المعجم الکبیر للطبراني (7/191)۔ مسند أحمد (5/16)۔ صحیح ابن خزیمۃ (2/326)"}],[425,"سیدنا سمرہ بن جندب رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’اگر تم جانتے ہو کہ میں نے اپنے رب کے پیغامات پہنچانے میں کسی قسم کی کوئی کوتاہی برتی ہے (تو مجھے بتا دو۔‘‘) صحابہ نے کہا: ’’ہم گواہی دیتے ہیں کہ آپ صلی اللہ علیہ وسلم نے اپنے رب کے پیغامات پہنچا دیے ہیں۔‘‘","",{"k":"المعجم الکبیر للطبراني (7/188 – 189)"}],[426,"سیدنا عبد اللہ بن عباس رضی اللہ عنہ نے آیت کریمہ:\n﴿ فَوَيۡلٌ لِّلَّذِينَ يَكۡتُبُونَ ٱلۡكِتَٰبَ بِأَيۡدِيهِمۡ ﴾ [البقرۃ: 79]\n’’ایسے لوگوں کے لیے ہلاکت ہے جو کتاب (فتویٰ وغیرہ) اپنے ہاتھوں سے (اپنی مرضی کے مطابق) لکھتے ہیں۔‘‘\nکے بارے میں فرمایا: ’’یہ اہل کتاب کے بارے میں نازل ہوئی ہے۔‘‘","",{"k":"السنن الکبری للنسائي (10991)"}],[427,"سیدنا عبداللہ بن عباس رضی اللہ عنہ نے فرمایا: ’’اے مسلمانو! تم اہل کتاب سے مختلف مسائل کے بارے میں کیوں پوچھتے رہتے ہو، حالانکہ تمہاری کتاب جو اللہ تعالیٰ نے تمہارے نبی صلی اللہ علیہ وسلم پر نازل کی ہے، وہ اللہ کے یہاں سے بالکل تازہ آئی ہے۔ وہ بالکل خالص ہے۔ اس میں کوئی ملاوٹ نہیں ہوئی اور اللہ تعالیٰ نے خود تمہیں بتا دیا ہے کہ اہل کتاب نے اللہ کی کتابوں کو بدل ڈالا ہے اور اس میں تغیر وتبدل کردیا ہے۔ وہ اپنے ہاتھوں سے ایک کتاب لکھتے اور دعویٰ کرتے کہ یہ اللہ کی طرف سے ہے تاکہ اس کے ذریعہ تھوڑی سی قیمت حاصل کریں۔ تمہیں اللہ تعالیٰ نے (قرآن و حدیث کا) جو علم دیا ہے، کیا وہ تمہیں ان سے پوچھنے سے منع نہیں کرتا؟ اللہ کی قسم! ہم تو ان کے کسی آدمی کو نہیں دیکھتے کہ جو کچھ تمہارے اوپر نازل ہوا ہے، اس کے متعلق وہ تم سے پوچھتا ہو۔‘‘","",{"k":"صحیح البخاري (7523)"}],[428,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’یہ روایت یونس نے معمر اور ابراہیم بن سعد سے اور انہوں نے زہری سے بیان کی ہے۔‘‘","",{"k":"صحیح البخاري (2685)"}],[429,"سیدنا عبد اللہ بن عباس رضی اللہ عنہ فرماتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم مدینہ تشریف لائے تو۔۔۔ پھر انہوں نے پوری حدیث بیان کی۔ اس میں یہ بھی تھا کہ اللہ تعالیٰ نے یہودیوں پر تورات میں آپس میں خونریزی کو حرام قرار دیا تھا۔ جب انہوں نے آپس میں خونریزی شروع کی تو یہ دو گروہ تھے جن کے ہاتھوں میں تورات موجود تھی اور وہ جانتے تھے کہ اس کے احکامات میں سے کیا ان کے حق میں ہے اور کیا ان کے خلاف ہے۔","",{"k":"تفسیر ابن جریر (1/397)۔ تفسیر ابن أبي حاتم (1/165 – 166)"}],[430,"سیدنا عمر بن خطاب رضی اللہ عنہ نے خطبہ دیتے ہوئے فرمایا: ’’رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں لوگوں کا وحی کے ذریعہ مواخذہ ہو جاتا تھا۔ لیکن اب وحی کا سلسلہ ختم ہو گیا ہے اور ہم اب صرف انہی امور میں مواخذہ کریں گے جو تمہارے اعمال میں سے ہمارے سامنے ظاہر ہوں گے۔ اس لیے جو کوئی ہمارے سامنے اچھا ئی ظاہر کرے گا، ہم اسے امن دیں گے اور اپنے قریب رکھیں گے۔ اس کے باطن سے ہمیں کوئی سروکار نہ ہو گا۔ اس کا حساب اللہ تعالیٰ کرے گا۔ اور جو کوئی ہمارے سامنے برائی ظاہر کرے گا تو ہم اسے نہ امن دیں گے اور نہ اس کی تصدیق کریں گے، خواہ وہ یہی کہتا رہے کہ اس کا باطن اچھا ہے۔‘‘","",{"k":"صحیح البخاري (2641)"}],[431,"امام بخاری رحمہ اللہ فرماتے ہیں: عثمان بن صالح نے اس کی متابعت کی ہے۔ اس کا کہنا ہے کہ مجھے ابن وہب نے خبر دی اور ابن وہب کہتے ہیں کہ مجھے یونس نے حدیث بیان کی۔"],[432,"اسے سلامہ نے عقیل سے روایت کیا ہے۔"],[433,"قتادہ رحمہ اللہ آیت کریمہ:\n﴿ ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡرِفُونَهُۥ كَمَا يَعۡرِفُونَ أَبۡنَآءَهُمۡۖ ﴾ [البقرۃ: 146]\n’’جن لوگوں کو ہم نے کتاب دی ہے وہ اس کو اتنی اچھی طرح پہچانتے ہیں جیسے اپنے بیٹوں کو پہچانتے ہیں‘‘\nکی تفسیر میں فرماتے ہیں: ’’وہ اسلام کو بطور دینِ الٰہی اور محمد صلی اللہ علیہ وسلم کو بطور رسول اللہ پہچانتے ہیں اور یہ ان کے پاس تورات اور انجیل میں لکھا ہوا ہے۔‘‘","",{"k":"تفسیر ابن أبي حاتم (4/1273)"}],[434,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’ابن عیینہ نے فرمان باری تعالیٰ:\n﴿ وَتَعِيَهَآ أُذُنٌ وَٰعِيَةٌ ﴾ [الحاقۃ: 12]\n’’اور یاد رکھنے والا کان اسے یاد رکھے۔‘‘\nکے بارے میں فرمایا: ’’کان اللہ کے احکامات کو یاد رکھتا ہے۔‘‘","",{"k":"مسند البزار: 8/179 عن أبي عمران الجوني"}],[435,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ حارث بن ہشام نے رسول اللہ صلی اللہ علیہ وسلم سے دریافت کیا: ’’آپ کے پاس وحی کیسے آتی ہے؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ”کبھی تو وہ گھنٹی کی گونج کی طرح آتی ہے اور یہ کیفیت مجھ پر بڑی گراں گزرتی ہے۔ جب یہ کیفیت ختم ہوتی ہے تو میں وہ وحی یاد کر چکا ہوتا ہوں۔ بسا اوقات ایسے بھی ہوتا ہے کہ میرے پاس فرشتہ انسانی شکل میں آتا ہے، پھر جو کچھ وہ کہتا ہے، میں اسے یاد کر لیتا ہوں۔“ سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں: ’’میں نے سخت ٹھنڈے دن میں آپ پر وحی کا نزول دیکھا ہے۔ پھر جب یہ وحی ختم ہوتی تو آپ صلی اللہ علیہ وسلم کی پیشانی سے پسینہ پھوٹ رہا ہوتا تھا۔‘‘","",{"k":"مؤطا مالك (2/12 – 15)۔ صحیح البخاري (2)۔ صحیح مسلم (2333)"}],[436,"اسماعیل از مالک از ہشام بن عروہ از عروہ بن زبیر از عائشہ از نبی کریم صلی اللہ علیہ وسلم مروی ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’بسا اوقات فرشتہ انسانی شکل میں میرے پاس آتا ہے اور اس کی کہی ہوئی بات میں یاد کرلیتا ہوں۔‘‘ بقیہ الفاظ پچھلی حدیث کی طرح ہیں۔","",{"k":"المعجم الکبیر للطبراني (3/259)"}],[437,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بسا اوقات فرشتہ ایک مرد کی شکل میں میرے پاس آتا ہے اور جو کہتا ہے، میں اسے یاد کرلیتا ہوں۔ بعض اوقات فرشتہ کی آمد گھنٹی کی گونج کی طرح ہوتی ہے۔ جب یہ کیفیت ختم ہوتی ہے تو میں اس کی کہی ہوئی بات یاد کرچکا ہوتا ہوں۔‘‘ بقیہ الفاظ پچھلی حدیث والے ہیں۔","",{"k":"صحیح البخاري (3215)"}],[438,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ حارث بن ہشام نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا کہ آپ صلی اللہ علیہ وسلم پر وحی کیسے نازل ہوتی ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’گھنٹی کی گونج کی طرح آواز آتی ہے اور جب وہ ختم ہوتی ہے تو میں وحی یاد کرچکا ہوتا ہوں۔‘‘","",{"k":"صحیح مسلم (2333)"}],[439,"علی از سفیان از ہشام از عروہ از عائشہ کی سند سے بھی یہ الفاظ منقول ہیں۔"],[440,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے اپنے رب عزوجل کی بات نقل کرتے ہوئے فرمایا کہ اللہ تعالیٰ فرماتے ہیں: ’’جو بندہ ایک بالشت میرے نزدیک ہوتا ہے، میں ایک ہاتھ کے برابر اس کے قریب ہوجاتا ہوں اور جو بندہ ایک ہاتھ کے برابر میرے نزدیک ہوتا ہے، میں دو ہاتھ کے برابر اس کے نزدیک ہوجاتا ہوں۔‘‘","",{"k":"صحیح البخاري (7405)۔ صحیح مسلم (2675)"}],[441,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے اپنے رب سے بیان کرتے ہوئے فرمایا کہ اللہ تعالیٰ فرماتے ہیں: ’’جب کوئی بندہ ایک بالشت میرے قریب ہوتا ہے تو میں ایک ہاتھ کے برابر اس کے نزدیک ہوتا ہوں۔ جب وہ ایک ہاتھ کے برابر میرے نزدیک ہوتا ہے تو میں دو ہاتھ کے برابر اس کے قریب ہوتا ہوں۔ اگر وہ چل کر میرے پاس آتا ہے تو میں دوڑ کر اس کے پاس جاتا ہوں۔‘‘","",{"k":"صحیح البخاري (7536)"}],[442,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے تمہارے رب سے روایت کرتے ہوئے کہا کہ اللہ تعالیٰ نے فرمایا: ’’ہر عمل کا ایک کفارہ ہوتا ہے۔ روزہ میرے لیے ہے اور میں ہی اس کی جزا دوں گا۔ بھوک کی وجہ سے روزہ دار کے منہ سے آنے والی بُو اللہ تعالیٰ کے نزدیک کستوری سے بھی زیادہ خوشبو دار ہوتی ہے۔ ‘‘","",{"k":"صحیح البخاري (7538)"}],[443,"حفص بن عمر از شعبہ از محمد بن زیاد از ابو ہریرہ از نبی کریم صلی اللہ علیہ وسلم کی سند سے بھی یہ حدیثِ قدسی مروی ہے۔","",{"k":"مسند أحمد (2/457)۔ مسند أبي داود الطیالسي (2485)"}],[444,"حجاج از شعبہ از محمد بن زیاد از ابو ہریرہ از نبی کریم صلی اللہ علیہ وسلم کی سند سے بھی یہ حدیثِ قدسی مروی ہے۔"],[445,"مسلم اور سلیمان از شعبہ از محمد بن زیاد از ابو ہریرہ از نبی کریم صلی اللہ علیہ وسلم کی سند سے بھی یہ حدیث ِ قدسی مروی ہے۔"],[446,"موسیٰ بن اسماعیل از حماد از ثابت از ابو رافع از ابو ہریرہ از نبی کریم صلی اللہ علیہ وسلم کی سند سے بھی یہ حدیث ِ قدسی مروی ہے۔","",{"k":"مسند أحمد (2/345، 2/510)۔ سنن أبي یعلیٰ (10/413)"}],[447,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے اپنے رب سے روایت کرتے ہوئے کہا کہ اللہ تعالیٰ نے فرمایا: ”بےشک اللہ تعالیٰ مومن پر اس کی نیکی کے سلسلے میں ظلم نہیں کرتا۔ اسے اس کی نیکی کی وجہ سے دنیا میں رزق عطا کیا جاتا ہے۔ (اور آخرت میں بھی اجر ملے گا۔) رہا کافر کا معاملہ تو اسے اس کی نیکیوں کا بدلہ دنیا میں چکا دیا جاتا ہے، جب وہ آخرت تک پہنچے گا تو اس کی کوئی نیکی باقی نہیں ہوگی جس کی اسے جزا دی جائے۔“","",{"k":"صحیح مسلم (2808)"}],[448,"سیدنا ابو ذر رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے اپنے رب عز وجل سے روایت کرتے ہوئے کہا کہ اللہ تعالیٰ نے فرمایا ہے: ’’ابن آدم! اگر تو زمین کے لگ بھگ گناہ لے کر میرے پاس آئے اور اس حال میں مجھے ملے کہ میرے ساتھ کسی بھی چیز کو شریک نہ کیا ہو تو میں تجھے (ان گناہوں کے) بقدر بخشش عطا کروں گا اور کوئی پروا نہیں کروں گا۔‘‘","",{"k":"صحیح مسلم (2687)"}],[449,"محمد بن ابی بکر کہتے ہیں کہ عمر بن علی نے بھی یہ روایت انہی الفاظ میں بیان کی اور ابتداء میں یہ کہا: ’’نبی کریم اپنے رب عز وجل سے روایت کرتے ہیں۔‘‘"],[450,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے اپنے رب سے بیان کرتے ہوئے کہا کہ اللہ تعالیٰ نے فرمایا: ’’میں نے ابن آدم سے قرض مانگا تو اس نے قرض نہ دیا اور مجھے برا بھلا کہہ دیا۔ بندہ کہتا ہے: ’’ہائے زمانہ! ہائے زمانہ!‘‘ حالانکہ اللہ ہی زمانہ ہے۔ ابن آدم کی ہر چیز مٹی کھا جاتی ہے سوائے ریڑھ کی ہڈی کے کہ اسی پر اللہ تعالیٰ بندے کو بنائیں گے یہاں تک کہ اسی سے اٹھائیں گے۔ ‘‘","",{"k":"مسند أحمد (2/300، 506)۔ صحیح ابن خزیمۃ (4/113)۔ صحیح البخاري (4814، 4935)۔ صحیح مسلم (2955)"}],[451,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو کہتے ہوئے سنا کہ اللہ تعالیٰ نے فرمایا: ’’میں اپنے بندے کے اس وقت تک ساتھ رہتا ہوں، جب تک وہ مجھے یاد کرتا ہے اور میرے ذکر سے اس کے ہونٹ ہلتے رہتے ہیں۔‘‘","",{"k":"الزھد لابن المبارك (956)۔ مسند أحمد (2/540)۔ صحیح ابن حبان (3/97)"}],[452,"ابراہیم یا مجاہد سے فرمان باری تعالیٰ:\n﴿ وَٱلَّذِي جَآءَ بِٱلصِّدۡقِ وَصَدَّقَ بِهِۦٓ ﴾ [الزمر: 33]\n’’اور وہ شخص جو سچ لے کر آیا اور جس نے اس کی تصدیق کی۔‘‘\nکی تفسیر میں منقول ہے کہ انہوں نے فرمایا: ’’اس سے اہل قرآن مراد ہیں جب وہ قرآن پر عمل کریں۔‘‘","",{"k":"تفسیر ابن جریر (24/4)۔ ذم الکلام للھروي (4/77)"}],[453,"نُعَیْم رحمہ اللہ فرماتے ہیں: ’’مخلوق کے ذریعہ پناہ مانگنا جائز ہے، نہ بندوں، جن وانس اور ملائکہ کے کلام کے ذریعہ۔‘‘ یہ قول اس بات کی دلیل ہے کہ کلام الٰہی مخلوق نہیں ہے، جبکہ اس کے علاوہ بقیہ تمام اشیاء مخلوق ہیں۔"],[454,"سیدنا عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ ولید بن ولید رضی اللہ عنہ نیند میں ڈر جاتے تھے۔ انہوں نے اس کا تذکرہ رسول اللہ صلی اللہ علیہ وسلم سے کیا تو آپ صلی اللہ علیہ وسلم نے انہیں فرمایا: ’’جب سونے کےلیے لیٹو تو یہ پڑھ لیا کرو: «بِسْمِ اللهِ، أَعُوذُ بِكَلِمَاتِ اللهِ التَّامَّةِ مِنْ غَضَبِهِ وَعِقَابِهِ وَمِنْ شَرِّ عِبَادِهِ وَمِنْ هَمَزَاتِ الشَّيَاطِينِ وَأَنْ يَحْضُرُونِ» ”اللہ کے نام سے(میں سوتا ہوں)، میں اللہ کے پورے کلمات کے ذریعہ اس کے غصہ سے، اس کے عذاب سے، اس کے بندوں کے شر سے اور شیاطین کے وسوسوں اور ان کے میرے پاس آنے سے پناہ میں آتا ہوں۔“ جب انہوں نے یہ دعاء پڑھی تو خوف دور ہوگیا۔ پھر عبداللہ بن عمرو رضی اللہ عنہ اپنے بالغ بیٹوں کو یہ دعا سکھاتے اور چھوٹے بچوں کو جو یاد نہیں کرسکتے تھے، لکھ کر اسے ان کے گلے میں لٹکا دیتے تھے۔","",{"k":"سنن أبي داود: 3893۔ السنن الکبری للنسائي: 6/191۔ سنن الترمذي (3528)۔ اس سند میں ابن اسحاق مدلس ہے اور اس نے سماع کی تصریح نہیں کی۔ یہ روایت ایک اور سند سے بھی مروی ہے، لیکن وہ منقطع ہے۔"}],[455,"سیدنا سعد بن ابی وقاص رضی اللہ عنہ بیان کرتے ہیں کہ میں نے خولہ بنت حکیم رضی اللہ عنہا سے سنا، وہ کہتی تھیں کہ رسول اللہ صلی اللہ علیہ وسلم کہا کرتے تھے: ’’جو شخص کسی منزل پر پڑاؤ ڈالنے کے بعد درج ذیل کلمات کہہ لے تو اسے وہاں سے کوچ کرنے تک کوئی چیز نقصان نہ پہنچا سکے گی: «أَعُوذُ بِكَلِمَاتِ اللهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ» ’’میں اللہ کے پورے کلمات کے ذریعہ ہر اس چیز کے شر سے جو اس نے پیدا کی ہے، پناہ لیتا ہوں۔‘‘","",{"k":"صحیح مسلم (2708)"}],[456,"یہ روایت عبد اللہ بن یوسف از لیث کی سند سے بھی مروی ہے۔"],[457,"آدم از لیث از یزید کی سند سے بھی یہ حدیث منقول ہے۔"],[458,"قتیبہ از لیث از یزید کی سند سے بھی یہ روایت بیان ہوئی ہے۔","",{"k":"صحیح مسلم (2708)"}],[459,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہےکہ اسلم قبیلہ کے ایک شخص نے کہا: ’’میں کل پوری رات سو نہیں سکا۔‘‘ رسول اللہ صلی اللہ علیہ وسلم نے دریافت فرمایا: ’’وہ کیوں؟‘‘ اس نے کہا: ’’مجھے ایک بچھو نے ڈس لیا تھا۔‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اگر تو شام کو یہ کہہ لیتا: «أَعُوذُ بِكَلِمَاتِ اللهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ» تو ان شاء اللہ وہ تجھے ضرر نہ دیتا۔‘‘","",{"k":"صحیح مسلم (2709)۔ مؤطا مالك (2/951)۔ صحیح ابن حبان (1021)"}],[460,"یہ واقعہ عیاش از عبد الاعلیٰ از عبید اللہ بن عمر کی سند سے بھی مروی ہے۔","",{"k":"صحیح ابن حبان (1039)"}],[461,"اصبغ از ابن وہب از جریر بن حازم از سہیل از ابیہ از ابو ہریرہ از نبی کریم صلی اللہ علیہ وسلم کی سند سے بھی یہ قصہ منقول ہے۔","",{"k":"صحیح ابن حبان (1022)"}],[462,"یہ واقعہ سعید بن تَلِید رُعَینی از ابن وہب از سعید بن عبد الرحمن جُمَحِی از سہیل کی سند سے بھی مروی ہے۔"],[463,"اصبغ از ابن وہب از سعید کی سند سے بھی یہ قصہ مروی ہے۔"],[464,"ہشام بن حسان اور محمد بن رفاعہ از سہیل از ابیہ از ابو ہریرہ از نبی کریم صلی اللہ علیہ وسلم کی سند سے بھی یہ حدیث مروی ہے۔","",{"k":"مسند أحمد (2/290)۔ عمل الیوم واللیلۃ للنسائي (590)۔ سنن الترمذي (3604)"}],[465,"زہری کہتے ہیں کہ مجھے طارق نے ابو ہریرہ سے اور انہوں نے نبی کریم صلی اللہ علیہ وسلم سے یہ واقعہ بیان کیا۔","",{"k":"السنن الکبری للنسائي (6/153 – 154)۔ سنن أبي داود (3899)"}],[466,"ان کے علاوہ شِبْل بن علاء بن عبد الرحمن از علاء ابن عبد الرحمن از عبد الرحمن از ابو ہریرہ از نبی کریم صلی اللہ علیہ وسلم کی سند سے بھی یہ روایت منقول ہے۔"],[467,"اسی طرح قعقاع از ابو صالح از ابو ہریرہ از نبی کریم صلی اللہ علیہ وسلم کی سند سے بھی مروی ہے۔","",{"k":"صحیح مسلم (2709)۔ السنن الکبری للنسائي (6/152)۔ التوحید لابن خزیمۃ (1/401)"}],[468,"سیدنا عبد اللہ بن عباس رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم حسن وحسین رضی اللہ عنہما کے لیے پناہ طلب کیا کرتے تھے اور فرماتے تھے کہ تمہارے بزرگ دادا (ابراہیم علیہ السلام) بھی ان کلمات کے ذریعہ اسماعیل اور اسحاق علیہما السلام کے لیے اللہ کی پناہ مانگا کرتے تھے: «أُعِيْذُكُمَا بِكَلِمَاتِ اللهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ» ”میں تمہارے لیے اللہ کے مکمل اور پورے کلمات کے وسیلے سے ہر شیطان اور ہلاک کرنے والے زہریلے کیڑے اور نظر بد سے پناہ مانگتا ہوں۔“"],[469,"سیدنا عبداللہ بن عباس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم حسن اور حسین رضی اللہ عنہما پر یہ کلمات پڑھ کر جھاڑ پھونک کرتے تھے: «أُعِيذُكُمَا بِكَلِمَاتِ اللهِ التَّامَّةِ، مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ» آپ صلی اللہ علیہ وسلم فرماتے تھے: ”اسماعیل اور اسحاق علیہما السلام کے لیے ابراہیم علیہ السلام اسی طرح پناہ مانگتے تھے۔“","",{"k":"عمل الیوم واللیلۃ للنسائي (1006)۔ سنن الترمذي (2060)۔ سنن ابن ماجہ (3525)"}],[470,"یہی روایت اصبغ نے ابن وہب سے اور انہوں نے سفیان ثوری سے بیان کی ہے۔"],[471,"سیدنا عبد اللہ بن عباس رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم حسن وحسین رضی اللہ عنہما کو ان کلمات کے ذریعہ اللہ کی پناہ میں دیتے تھے: «أُعِيذُكُمَا بِكَلِمَاتِ اللهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ»"],[472,"عبد اللہ بن ابی شیبہ نے ابن فُضیل سے، انہوں نے اعمش سے، انہوں نے منہال سے اور انہوں نے محمد بن علی سے بیان کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم حسن وحسین کو اللہ کی پناہ میں دیا کرتے تھے۔ پھر انہوں نے اوپر والے الفاظ بیان کیے۔"],[473,"نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’قرآن پڑھا کرو۔‘‘","",{"k":"صحیح البخاري (5060)۔ صحیح مسلم (2667)"}],[474,"آپ صلی اللہ علیہ وسلم نے صحابہ کرام رضی اللہ عنہم کو بلندی پر چڑھتے ہوئے آواز بلند کرنے سے منع فرمایا۔"],[475,"یہ روایت ہمیں احمد بن اسحاق نے بیان کی۔ وہ کہتے ہیں کہ ہمیں انصاری نے بیان کیا۔ وہ کہتے ہیں کہ ہمیں تیمی نے ابو عثمان سے اور انہوں نے ابو موسیٰ سے بیان کیا۔ابو موسیٰ رضی اللہ عنہ کہتے ہیں کہ ایک مرتبہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ کسی سفر میں تھے۔ دورانِ سفر ہم کسی دشوار گزار گھاٹی یا عام گھاٹی پر چڑھے تو ہم میں سے ہر آدمی نے اوپر چڑھ کر کہا: «لَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ» تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’تم کسی غائب یا بہرے کو نہیں پکار رہے ہو۔‘‘ ابوموسیٰ رضی اللہ عنہ کہتے ہیں کہ آپ صلی اللہ علیہ وسلم اس وقت خچر پر سوار تھے اور اسے ہانک رہے تھے۔ پھر آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اے ابو موسیٰ! یا اے عبد اللہ! تمہیں جنت کے خزانوں میں سے ایک خزانے کا بتاؤں؟‘‘ میں نے جواب دیا: ’’ضرور! یا رسول اللہ!‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’وہ خزانہ یہ ہے: «لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللِّهِ» ’’نیکی کرنے کی طاقت اور بدی سے بچنے کی استطاعت صرف اللہ کی توفیق سے ہی ممکن ہے۔‘‘","",{"k":"صحیح البخاري (6409، 2992)۔ صحیح مسلم (2704)"}],[476,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’نبی کریم صلی اللہ علیہ وسلم کے بارے میں مروی ہے کہ آپ صلی اللہ علیہ وسلم کو یہ پسند تھا کہ بندے کی آواز آہستہ ہو۔ جبکہ آواز کا اونچا ہونا آپ صلی اللہ علیہ وسلم کو ناپسند تھا۔‘‘","",{"k":"المعجم الکبیر للطبراني: 7736۔ امام ہیثمی نے مجمع الزوائد: 8/114 میں لکھا ہے کہ اس کی سند میں مسلمہ بن علی خشنی ضعیف راوی ہے۔ ابن عدی نے الکامل فی ضعفاء الرجال: 6/313، رقم: 1799 میں اس روایت کو مسلمہ کی منکر روایات کی مثال میں پیش کیا ہے اور پھر ائمہ سے اس کی تضعیف نقل کی ہے، مثلاً امام بخاری نے اسے منکر الحدیث کہا ہے اور امام نسائی نے متروک الحدیث قرار دیا ہے۔ اس کے حالات کو بیان کرکے آخر میں امام ابن عدی نے فرمایا: ’’مسلمہ کی تمام روایات جنہیں میں نے ذکر کیا ہے یا چھوڑ دیا ہے، سب یا زیادہ تر غیر محفوظ ہیں۔‘‘"}],[477,"اللہ عز وجل ایسی آواز سے پکارتے ہیں جسے دور والے بھی ویسے ہی سنتے ہیں جیسے قریب والے اور یہ صفت صرف اللہ تعالیٰ کی ہے۔"],[478,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’مذکورہ حدیث اس بات کی دلیل ہے کہ اللہ تعالیٰ کی آواز مخلوق کی آواز کے مشابہ نہیں ہے۔ کیونکہ اللہ کی آواز دور سے بھی ویسے ہی سنائی دیتی ہے جیسے قریب سے، اور آوازِ الٰہی سے فرشتے بےہوش ہوجاتے ہیں۔ ویسے جب فرشتے ایک دوسرے کو آواز دیتے ہیں تو بےہوش نہیں ہوتے۔‘‘"],[479,"فرمان الٰہی ہے:\n﴿ فَلَا تَجۡعَلُواْ لِلَّهِ أَندَادًا ﴾ [البقرۃ: 22]\n’’پس اللہ کے لیے کسی قسم کے شریک نہ بناؤ۔‘‘\nلہٰذا اللہ کی صفت کا نہ تو کوئی شریک ہے، نہ مثیل اور نہ ہی اس کی کوئی صفت مخلوق میں پائی جاتی ہے۔"],[480,"یہ حدیث ہمیں داؤد بن شبیب نے بیان کی، وہ کہتے ہیں کہ ہمیں ہمام نے بتایا۔ وہ کہتے ہیں کہ ہمیں قاسم بن عبد الواحد نے بیان کیا۔ وہ کہتے ہیں کہ مجھے عبد اللہ بن محمد بن عقیل نے بتایا کہ جابر بن عبد اللہ رضی اللہ عنہ نے انہیں بیان کیا کہ انہوں نے عبد اللہ بن اُنَیْس رضی اللہ عنہ سے سنا، وہ کہتے تھے کہ میں نے نبی کریم صلی اللہ علیہ وسلم کو کہتے ہوئے سنا: ’’اللہ تعالیٰ بندوں کو جمع کریں گے اور پھر انہیں ایسی آواز سے پکاریں گے جسے دور والا بھی ویسے ہی سنے گا جیسے قریب والا سنے گا۔ اللہ تعالیٰ فرمائیں گے: ’’میں بادشاہ ہوں۔ میں قاضی اور حاکم ہوں۔ کسی جنتی کے لیے مناسب نہیں کہ وہ جنت میں چلا جائے جبکہ کوئی دوزخی اس سے کسی ظلم کا بدلہ لینا چاہتا ہو۔‘‘","",{"k":"نمبر 90 کے تحت اس کی تخریج گزر چکی ہے۔"}],[481,"سیدنا ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’روزِ قیامت اللہ عز وجل آواز دیں گے: ’’آدم!‘‘ آدم علیہ السلام عرض کریں گے: ’’حاضر ہوں اے ہمارے رب! اور اطاعت کےلیے تیار ہوں۔‘‘ تو اللہ تعالیٰ آواز سے پکاریں گے کہ اللہ تعالیٰ تمہیں حکم دیتے ہیں کہ تم اپنی اولاد میں سے ایک جماعت دوزخ کےلیے نکالو۔‘‘ آدم علیہ السلام پوچھیں گے: ’’میرے رب! آگ کا حصہ کتنا ہے؟‘‘ اللہ تعالیٰ فرمائیں گے: ’’ہر ہزار میں سے نو سو ننانوے۔‘‘ اس وقت ہر حاملہ اپنا حمل گرا دے گی اور لوگ تمہیں نشے کی حالت میں نظر آئیں گے، جبکہ وہ نشے میں نہیں ہوں گے، دراصل اللہ کا عذاب بہت سخت ہے۔‘‘","",{"k":"صحیح البخاري (7483)۔ صحیح مسلم (222)"}],[482,"امام مسروق رحمہ اللہ کہتے ہیں کہ اگر ہم نے ابن مسعود رضی اللہ عنہ سے اس آیت کی تفسیر نہ پوچھی ہوتی تو کون ہمیں بتاتا:\n﴿ حَتَّىٰٓ إِذَا فُزِّعَ عَن قُلُوبِهِمۡ ﴾ [سبأ: 23]\n’’یہاں تک کہ جب ان کے دلوں سے گھبراہٹ دور کی جاتی ہے۔‘‘\nابن مسعود رضی اللہ عنہ نے فرمایا: ’’اہل آسمان ایسی آواز سنتے ہیں جیسی پتھر پر زنجیر کے رگڑنے سے نکلتی ہے۔ اس آواز کو سن کر وہ گر جاتے ہیں۔ پھر جب ان کے دلوں سے گھبراہٹ دور ہوجاتی ہے اور آواز ختم ہوجاتی ہے تو وہ جان لیتے ہیں کہ یہ وحی ہے۔ پھر وہ ایک دوسرے کو آواز دیتے ہیں: ’’تمہارے رب نے کیا کہا؟‘‘ وہ جواب دیتے ہیں: ’’جو بھی کہا ہے، حق ہے۔‘‘\nعربی کتاب میں 482 کے بعد 484 نمبر ہے۔483 نمبر نہیں دیا گیا۔","",{"k":"السنۃ لعبد اللہ بن أحمد: رقم: 536 – 537۔ التوحید لابن خزیمۃ: 208، 210 – 211۔ تفسیر ابن جریر: 22/90۔ یہ مرفوعاً بھی مروی ہے۔ دیکھیے: سنن أبي داود: 4738۔ الرد علی الجہمیۃ لابن أبي حاتم بحوالہ فتح الباري: 13/456۔ اہل علم کے مطابق اس روایت کا موقوف ہونا ہی راجح ہے۔ دیکھیے: العلل للدارقطني: 5/243۔ تاریخ بغداد: 11/392 – 393۔ بہرحال موقوف بھی تسلیم کیا جائے تو حکماً مرفوع ہے جیسا کہ علامہ البانی نے کہا ہے۔ دیکھیے: سلسلۃ الأحادیث الصحیحۃ: 3/282، رقم: 1293"}],[483,"یہی روایت عمر بن حفص نے اپنے والد سے، انہوں نے اعمش سے، انہوں نے مسلم سے، انہوں نے مسروق سے اور انہوں نے عبد اللہ بن مسعود رضی اللہ عنہ سے بیان کی ہے۔","",{"k":"تخریج گزر چکی ہے۔ اس سند میں اعمش کے سماع کی تصریح ہے۔"}],[484,"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب اللہ تعالیٰ آسمان پر کسی بات کا فیصلہ کرتے ہیں تو فرشتے اللہ تعالیٰ کے فیصلہ کو سن کر جھک کر عاجزی کرتے ہوئے اپنے پَر پھڑپھڑاتے ہیں۔ اللہ کا فرمان انہیں اس طرح سنائی دیتا ہے جیسے صاف چکنے پتھر پر زنجیر چلانے سے آواز پیدا ہوتی ہے۔ پھر جب ان کے دلوں سے گھبراہٹ دور ہو جاتی ہے تو وہ آپس میں پوچھتے ہیں کہ تمہارے رب نے کیا فرمایا؟ وہ جواب دیتے ہیں کہ حق بات کا حکم فرمایا ہے اور وہ بہت اونچا، سب سے بڑا ہے۔‘‘","",{"k":"صحیح البخاري (4800)"}],[485,"سیدنا عبد اللہ بن عباس رضی اللہ عنہ فرماتے ہیں: ’’جب اللہ تعالیٰ کسی کام کا فیصلہ کرتے ہیں اور کلام کرتے ہیں تو زمین وآسمان اور پہاڑ تھرتھرا اُٹھتے ہیں اور سارے فرشتے سجدے میں گر جاتے ہیں۔‘‘","",{"k":"اس سے ملتے جلتے مفہوم کے ساتھ یہ روایت الدر المنثور: 5/442 اور فتح الباري: 8/538 میں موجود ہے۔"}],[486,"سیدنا عبد اللہ بن عباس رضی اللہ عنہ چند انصاری صحابہ سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں کہا: ’’ان ٹوٹنے والے ستاروں کے بارے میں تم کیا کہا کرتے ہو؟‘‘ انہوں نے کہا: ’’یا رسول اللہ! جب ہم انہیں ٹوٹتا ہوا دیکھتے تھے تو یہ کہتے تھے کہ کوئی بادشاہ فوت ہوگیا ہے، یا کوئی بچہ پیدا ہوا ہے یا کوئی بچہ دنیا سے چلا گیا ہے۔‘‘ تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’بات یہ نہیں ہے۔ دراصل جب اللہ تعالیٰ اپنی مخلوق کے حوالہ سے کوئی فیصلہ فرماتے ہیں تو اسے سن کر آسمان والے تسبیح کرتے ہیں۔ ان کی تسبیح سن کر ان سے نیچے والے بھی تسبیح شروع کردیتے ہیں۔ پھر ان کی تسبیح سن کر ان سے نیچے والے تسبیح کرتے ہیں۔ اس طرح تسبیح کا یہ سلسلہ چلتے چلتے آسمانِ دنیا تک پہنچ جاتا ہے، یہاں تک ایک فرشتہ دوسرے سے پوچھتا ہے: ’’تم تسبیح کیوں کررہے ہو؟‘‘ وہ جواب دیتا ہے کہ ہم سے اوپر والے تسبیح کررہے تھے، اس لیے ہم نے بھی تسبیح شروع کردی۔ سوال کرنے والا کہتا ہے: ’’تم ان سے پوچھتے کیوں نہیں کہ کیوں تسبیح کررہے ہو؟‘‘ تو وہ اوپر والوں سے سوال کرتے ہیں تو اوپر والے جواب دیتے ہیں: ’’اللہ تعالیٰ نے اپنی مخلوق کے حوالہ سے فلاں فلاں فیصلہ کیا ہے۔‘‘اس کام کا نام لیتے ہیں جو ہونا ہوتا ہے۔ اس طرح یہ جواب ایک آسمان سے دوسرے آسمان تک پہنچتا ہے، یہاں تک کہ آسمانِ دنیا تک پہنچ جاتا ہے۔ آسمانِ دنیا والے آپس میں بات چیت کرتے ہیں تو شیاطین ان کی بات کو اچک لیتے ہیں، لیکن اس بات کو اچکتے ہوئے انہیں وہم اور اختلاف لاحق ہوجاتا ہے۔پھر یہ بات وہ زمین میں بسنے والے کاہنوں کے پاس لاتے ہیں اور انہیں بتاتے ہیں۔ کچھ صحیح اور کچھ غلط ان کے کان میں پھونکتے ہیں۔ پھر کاہن آگے لوگوں تک یہ بات پہنچا دیتے ہیں۔ پھر اللہ عز وجل نے ان ستاروں کے ذریعہ ان شیاطین کو آسمان تک پہنچنے سے روک دیا جس سے کہانت ختم ہوگئی۔ آج کوئی کہانت باقی نہیں رہی۔‘‘","",{"k":"سیرۃ ابن ھشام: 1/207۔ مختصراً یہ روایت صحیح مسلم (2229) میں بھی ہے۔"}],[487,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ میں نے پوچھا: ’’یا رسول اللہ! سب سے بڑا گناہ کون سا ہے؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’یہ کہ تم اللہ کا کوئی شریک بناؤ، حالانکہ اس نے تمہیں پیدا کیا ہے۔‘‘ میں نے پوچھا: ’’پھر کون سا؟‘‘ فرمایا: ’’یہ کہ تم اپنی اولاد اس ڈر سے قتل کردو کہ تمہارے ساتھ کھانے میں شریک ہوگی۔‘‘ پوچھا: ’’پھر کون سا؟‘‘ فرمایا: ’’یہ کہ تم اپنے پڑوسی کی بیوی سے منہ کالا کرو۔‘‘ آپ صلی اللہ علیہ وسلم کے ان جوابات کی تصدیق میں اللہ عزوجل نے یہ آیت نازل فرمائی:\n﴿ وَٱلَّذِينَ لَا يَدۡعُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ وَلَا يَقۡتُلُونَ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّ وَلَا يَزۡنُونَۚ وَمَن يَفۡعَلۡ ذَٰلِكَ يَلۡقَ أَثَامًا ﴾ [الفرقان: 68]\n’’اور (رحمن کے بندے) اللہ کے ساتھ کسی اور الٰہ کو نہیں پکارتے، نہ ہی اللہ کی حرام کی ہوئی کسی جان کو ناحق قتل کرتے ہیں اور نہ زنا کرتے ہیں۔ اور جو شخص ایسے کام کرے گا، ان کی سزا پاکے رہے گا۔‘‘","",{"k":"صحیح البخاري (6001)۔ صحیح مسلم (86)"}],[488,"مسدد نے یحییٰ سے، انہوں نے سفیان سے، انہوں سے منصور اور سلیمان سے اور ان دونوں نے ابو وائل سے اسی طرح کے الفاظ نقل کیے ہیں۔","",{"k":"صحیح البخاري (476)"}],[489,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ میں نے نبی کریم صلی اللہ علیہ وسلم سے دریافت کیا: ’’کون سا گناہ سب سے بڑا ہے؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’تمہارا کسی کو اللہ کا شریک بنانا، حالانکہ اس نے تمہیں پیدا کیا ہے۔‘‘","",{"k":"صحیح البخاري (4477)۔ صحیح مسلم (86)"}],[490,"قتیبہ کہتے ہیں ہمیں جریر نے اسی طرح کی روایت سنائی۔","",{"k":"صحیح البخاري (7520)"}],[491,"آیت کریمہ:\n﴿ وَمَا يُؤۡمِنُ أَكۡثَرُهُم بِٱللَّهِ إِلَّا وَهُم مُّشۡرِكُونَ ﴾ [یوسف: 106]\n’’اور ان میں سے اکثر لوگ ایسے ہیں کہ اللہ پر ایمان رکھتے بھی ہیں تو اس طرح کہ وہ اس کے ساتھ شرک بھی کرتے جاتے ہیں۔‘‘\nکی تفسیر میں عکرمہ رحمہ اللہ فرماتے ہیں: ’’اللہ تعالیٰ مشرکین سے پوچھتے ہیں کہ تمہیں اور زمین وآسمان کو کس نے بنایا ہے؟‘‘ وہ کہتے ہیں: ’’اللہ نے۔‘‘ یہ ان کا ایمان ہے جبکہ پوجا وہ غیر اللہ کی کرتے ہیں۔‘‘","",{"k":"تفسیر ابن جریر (13/77)۔ تفسیر ابن أبي حاتم (7/2207)"}],[492,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’انگوٹھیوں اور سفید درہموں پر اللہ تعالیٰ کا ذکر (نقش)ہوتا ہے۔‘‘"],[493,"عطاء (بن ابی رباح رحمہ اللہ، المتوفیٰ: 114ھ) فرماتے ہیں: ’’انگوٹھی پر اللہ تعالیٰ کا ذکر (نقش) ہو اور انسان اپنے پہن کر بیت الخلاء میں چلا جائے یا اپنی بیوی سے ملاپ کرے جبکہ انگوٹھی اس کی انگلی میں ہو تو کوئی حرج نہیں۔‘‘","",{"k":"مصنف عبد الرزاق (1/346)"}],[494,"حسن رحمہ اللہ بھی اسی کے قائل ہیں اور ان کا کہنا ہے کہ سفید درہموں کو بغیر وضوء کے چھونا جائز ہے۔ اس کے علاوہ (بلا وضوء) مصحف کو ایک جگہ سے اٹھا کر دوسری جگہ رکھنا بھی درست ہے۔","",{"k":"فضائل القرآن لأبي عبید (2/239)۔ مصنف عبد الرزاق (1/342)۔ مصنف ابن أبي شیبۃ (1/113، 2/362)"}],[495,"سیدنا انس رضی اللہ عنہ کے بارے میں منقول ہے کہ وہ بلا وضوء درہموں کو چھو لیا کرتے تھے۔"],[496,"سیدنا عبد اللہ بن عباس رضی اللہ عنہ فرماتے ہیں کہ انسان مصحف کو اپنے اس بستر پر رکھ سکتا ہے جس پر اسے احتلام ہوتا ہے یا وہ اپنی بیوی سے جماع کرتا ہے یا اس کا پسینہ اس پر بہتا ہے۔‘‘","",{"k":"فضائل القرآن لأبي عبید: 2/240۔ مصنف عبد الرزاق: 1/342۔ المصاحف لابن أبي داود، ص: 216۔ یہی قول عطاء سے بھی مروی ہے۔"}],[497,"ایک مرتبہ سعید بن جُبَیْر نے پیشاب کرنے کے بعد وضوء کیا، لیکن پاؤں نہیں دھوئے۔ پھر مصحف تھام لیا۔","",{"k":"مصنف عبد الرزاق (1/345)۔ المصاحف لابن أبي داود (ص 215)"}],[498,"امام طاؤس رحمہ اللہ فرماتے ہیں کہ اگر کسی آدمی نے پٹکے میں درہم رکھے ہوئے ہوں تو وہ اس پٹکے کو باندھ کر قضائے حاجت کرسکتا ہے۔"],[499,"ابراہیم رحمہ اللہ فرماتے ہیں کہ لوگوں کا اپنے اخراجات (کےلیے درہم ودینار کو ساتھ رکھے بغیر) گزارا نہیں ہوسکتا۔","",{"k":"مصنف عبد الرزاق (3/344)۔ مصنف ابن أبي شیبۃ (1/113)"}],[500,"بعض تابعین اس چیز کو اچھا سمجھتے تھے کہ جس انگوٹھی پر اللہ کا ذکر مکتوب ہو، اسے بیت الخلاء میں نہ لے جایا جائے۔","",{"k":"مصنف ابن أبي شیبۃ (1/112)"}],[501,"امام بخاری رحمہ اللہ فرماتے ہیں کہ یہ قول حرمت کی بجائے ناپسندیدگی پر محمول کیا جائے تو درست ہے۔"],[502,"نبی کریم صلی اللہ علیہ وسلم کا فرمان ہے کہ اپنے آباءواجداد اور مسیح علیہ السلام کی قسم نہ کھاؤ۔","",{"k":"صحیح البخاري (6648، 7401)۔ صحیح مسلم (1646)۔ مسیح علیہ السلام کا تذکرہ اس میں نہیں۔ مصنف ابن أبي شیبۃ: 3/80 – 81 میں ایک مرسل روایت میں مسیح علیہ السلام کی قسم کھانے کا تذکرہ ہے۔"}],[503,"کسی کےلیے جائز نہیں کہ مخلوقات میں سے کسی کی یا ان کے اعمال اور کلام کی یا کفار ومنافقین کے کلام کی یا ابلیس کے قول کی قسم کھائے۔ جو بندہ مجوس وغیرہ کے قول کی قسم کھاتا ہے، اس پر گناہ لازم نہیں آتا۔"],[504,"یہ قول ابن مسعود رضی اللہ عنہ اور ابراہیم رحمہ اللہ سے منقول ہے۔","",{"k":"مصنف عبد الرزاق (8/472)۔ سنن سعید بن منصور (2/434 – 436، 438)۔ الإبانۃ لابن بطۃ (1/265 – 266)"}],[505,"نبی کریم صلی اللہ علیہ وسلم سے مرسلاً مروی ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص نے قرآن کی کسی سورت کی قسم کھائی، اس پر لازم ہے کہ اس سورت کی ہر آیت کے بدلہ میں کفارہ دے۔‘‘","",{"k":"المراسیل لأبي داود (ص 282)۔ الإبانۃ لابن بطۃ (1/263 – 264)۔ السنن الکبری للبیھقي (10/43)"}],[506,"جبکہ وہی بندہ اگر مخلوق کی آواز کی قسم کھائے تو اس پر کفارہ لازم نہیں آتا۔"],[507,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں جب ابو بکر رضی اللہ عنہ خلیفہ بنے تو انہوں نے انہیں (یعنی انس بن مالک رضی اللہ عنہ کو) بحرین بھیجا اور انہیں یہ خط لکھ کر دیا۔ مہر کی لکھائی تین سطروں میں تھی۔ ایک سطر میں ’’محمد‘‘ لکھا تھا، دوسری میں ’’رسول‘‘ اور تیسری میں ’’اللہ‘‘۔","",{"k":"صحیح البخاري (3106، 5878)"}],[508,"سیدنا انس رضی اللہ عنہ فرماتے تھے: ’’رسول اللہ صلی اللہ علیہ وسلم نے ایک انگوٹھی پہنی، گویا میں آپ صلی اللہ علیہ وسلم کے ہاتھ میں اس کی چمک کو دیکھ رہا ہوں۔ اس پر ’’محمد رسول اللہ‘‘ نقش تھا۔‘‘","",{"k":"صحیح البخاري (2938)۔ صحیح مسلم (2092)"}],[509,"سیدنا انس رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک انگوٹھی بنوائی اور فرمایا: ’’ہم نے ایک انگوٹھی بنوائی ہے اس پر لفظ («محمد رسول الله») کندہ کرایا ہے اس لیے کوئی شخص (اپنی انگوٹھی پر) یہ نقش کندہ نہ کرائے۔‘‘","",{"k":"صحیح البخاري (5874)"}],[510,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک انگوٹھی بنوائی اور اس میں یہ نقش کھدوایا: «محمد رسول الله»","",{"k":"صحیح البخاري (5877)"}],[511,"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت ہےکہ رسول اللہ صلی اللہ علیہ وسلم نے ایک انگوٹھی بنائی، جس پر”محمد رسول اللہ“ کندہ تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”کوئی اپنی انگوٹھی پر میری انگوٹھی کا نقش کندہ نہ کرائے۔“","",{"k":"صحیح مسلم (2091)"}],[512,"سیدنا عبد اللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی انگوٹھی پر ’’محمد رسول اللہ‘‘ لکھا ہوا تھا۔","",{"k":"مسند أحمد (2/94)۔ سنن النسائي (8/192)۔ صحیح البخاري (5866)"}],[513,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’نبی کریم صلی اللہ علیہ وسلم نے ایک خط لکھا جس میں ’’بسم اللہ الرحمن الرحیم‘‘ لکھا۔ اس خط کو قیصر کے ترجمان نے قیصر اور اس کے درباریوں کے سامنے پڑھا تھا۔ بلاشبہ کفار اور اہل کتاب کی قراءت ان کے اعمال ہیں۔ جبکہ پڑھی جانے والی چیز عزیز ومنان کا کلام ہے، مخلوق ہرگز نہیں ہے۔‘‘"],[514,"لہٰذا جو شخص قیصر اور ذاتِ باری تعالیٰ کے اقراری مشرکین کی آواز کی قسم کھاتا ہے، اس کی قسم واقع نہیں ہوتی کیونکہ وہ اللہ کے علاوہ کسی اور کی قسم کھاتا ہے اور نبی کریم صلی اللہ علیہ وسلم نے فرمایا ہے: ’’اللہ کے علاوہ کسی کی قسم نہ کھاؤ۔‘‘","",{"k":"مسند أحمد: 3/487۔ مصنف عبد الرزاق: 8/466۔ علامہ ہیثمی رحمہ اللہ فرماتے ہیں کہ اس کی سند میں عبد الکریم بن ابی المخارق ضعیف راوی ہے۔ مجمع الزوائد: 1/205 و 4/177"}],[515,"کسی کے لیے جائز نہیں کہ وہ انگوٹھیوں، سفید درہموں اور بچوں کی ان تختیوں کی قسم کھائے جس پر بچے بار بار لکھتے اور مٹاتے رہتے ہیں۔ اگر کسی نے قسم کھا لی تو اس کی قسم واقع نہیں ہوگی کیونکہ فرمان باری تعالیٰ ہے:\n﴿ فَلَا تَجۡعَلُواْ لِلَّهِ أَندَادًا ﴾ [البقرۃ: 22]\n’’پس اللہ کے لیے کسی قسم کے شریک نہ بناؤ۔‘‘"],[516,"سیدنا عبد اللہ بن عباس رضی اللہ عنہ بیان کرتے ہیں کہ مجھے سیدنا ابو سفیان بن حرب رضی اللہ عنہ نے بتایا کہ ہرقل نے انہیں پیغام بھیج کر بلایا اور رسول اللہ صلی اللہ علیہ وسلم کے اس خط کو بھی منگوایا جو رسول اللہ صلی اللہ علیہ وسلم نے سیدنا دِحْیہ کلبی رضی اللہ عنہ کو دے کر سردارِ بُصری کے پاس بھیجا تھا اور اس نے وہ خط ہرقل تک پہنچا دیا تھا۔ جب ہرقل نے اسے پڑھا تو اس میں لکھا تھا: ’’بسم اللہ الرحمن الرحیم، اللہ کے بندے اور رسول محمد کی طرف سے سردارِ روم ہرقل کے نام! ہدایت کی پیروی کرنے والے پر سلامتی نازل ہو۔ اما بعد!\n﴿ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ تَعَالَوۡاْ إِلَىٰ كَلِمَةٍ سَوَآءِۭ بَيۡنَنَا وَبَيۡنَكُمۡ أَلَّا نَعۡبُدَ إِلَّا ٱللَّهَ وَلَا نُشۡرِكَ بِهِۦ شَيۡـًٔا وَلَا يَتَّخِذَ بَعۡضُنَا بَعۡضًا أَرۡبَابًا مِّن دُونِ ٱللَّهِۚ فَإِن تَوَلَّوۡاْ فَقُولُواْ ٱشۡهَدُواْ بِأَنَّا مُسۡلِمُونَ ﴾ [آل عمران: 64]\n’’اے اہل کتاب! ایک ایسی بات کی طرف آجاؤ جو ہم تم میں مشترک ہے (اور وہ یہ) کہ ہم اللہ کے سوا کسی کی عبادت نہ کریں، اور اس کے ساتھ کسی کو شریک نہ ٹھہرائیں، اور اللہ کو چھوڑ کر ہم ایک دوسرے کو رب نہ بنائیں۔ پھر بھی اگر وہ منہ موڑیں تو کہہ دو: ’’گواہ رہنا کہ ہم مسلمان ہیں۔‘‘\nجب اس نے پورے خط کو پڑھ لیا تو دربار میں شور مچ گیا اور آوازیں بلند ہوگئیں اور ہمیں وہاں سے نکال دیا گیا۔‘‘","",{"k":"صحیح البخاري (7)۔ صحیح مسلم (1773)"}],[517,"یحییٰ بن بکیر نے لیث سے یہ روایت بیان کی ہے۔","",{"k":"صحیح البخاري (7264)"}],[518,"ایک اور سند سے بھی یہ واقعہ منقول ہے۔ اس میں ہے کہ جب ہرقل نے خط پڑھا تو اس میں لکھا تھا: ’’بسم اللہ الرحمن الرحیم، اللہ کے بندے اور رسول محمد کی طرف سے۔۔۔‘‘","",{"k":"صحیح البخاري (7264)"}],[519,"ایک اور سند سے بھی یہ واقعہ مروی ہے، اس میں ہے کہ جب ہرقل نے رسول اللہ صلی اللہ علیہ وسلم کا خط منگوایا اور اسے پڑھا گیا تو اس میں لکھا تھا: ’’بسم اللہ الرحمن الرحیم، اور ﴿ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ تَعَالَوۡاْ إِلَىٰ كَلِمَةٍ سَوَآءِۭ بَيۡنَنَا وَبَيۡنَكُمۡ أَلَّا نَعۡبُدَ إِلَّا ٱللَّهَ وَلَا نُشۡرِكَ بِهِۦ شَيۡـًٔا وَلَا يَتَّخِذَ بَعۡضُنَا بَعۡضًا أَرۡبَابًا مِّن دُونِ ٱللَّهِۚ فَإِن تَوَلَّوۡاْ فَقُولُواْ ٱشۡهَدُواْ بِأَنَّا مُسۡلِمُونَ ﴾ [آل عمران: 64] جب اس نے مکمل خط کو پڑھ لیا تو اس کے ارد گرد بیٹھے ہوئے سردارانِ روم کی آوازیں بلند ہوگئیں اور دربار میں شور مچ گیا۔‘‘","",{"k":"صحیح البخاري (49 – 51، 2940)"}],[520,"سیدنا عبد اللہ بن عباس رضی اللہ عنہ بیان کرتے ہیں کہ مجھے سیدنا ابو سفیان بن حرب رضی اللہ عنہ نے یہ واقعہ سنایا۔ اس میں یہ بھی تھا کہ ہرقل کے پاس سیدنا دحیہ بن خلیفہ رضی اللہ عنہ کے ذریعہ رسول اللہ صلی اللہ علیہ وسلم کا خط پہنچا۔ اس میں لکھا تھا: ’’بسم اللہ الرحمن الرحیم‘‘","",{"k":"صحیحین کا حوالہ گزر چکا ہے۔"}],[521,"امام بخاری رحمہ اللہ فرماتے ہیں: یہ روایت معمر اور ہلال بن رداد از زہری کی سند سے بھی مروی ہے۔","",{"k":"صحیح البخاري (4553)۔ صحیح مسلم (1773)"}],[522,"سیدنا عبد اللہ بن عباس رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک صحابی کو کسریٰ کےلیے خط دے کر بھیجا اور اسے کہا کہ یہ خط سردارِ بحرین کے حوالہ کردینا تاکہ وہ اسے کسریٰ تک پہنچا دے۔ جب کسریٰ (تک وہ خط پہنچا اور اس)نے وہ خط پڑھا تو اسے پھاڑ دیا۔حدیث کے ایک راوی کہتے ہیں کہ میرے خیال میں سعید بن مسیب نے کہا تھا: ’’پھر رسول اللہ صلی اللہ علیہ وسلم نے ان لوگوں کے خلاف بددعاء کی کہ انہیں ہر اعتبار سے ٹکڑے ٹکڑے کردیا جائے۔‘‘","",{"k":"519 نمبر کے تحت تخریج گزر چکی ہے۔"}],[523,"عبد اللہ بن یوسف از لیث از عُقَیْل از ابن شہاب کے واسطے سے بھی یہ روایت مروی ہے۔","",{"k":"صحیح البخاري (2939)"}],[524,"یحییٰ بن بکیر از لیث از یونس از ابن شہاب از عبید اللہ کی سند سے مروی ہے کہ ابن عباس رضی اللہ عنہ نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنا ایک خط دے کر ایک صحابی کو کسریٰ کی طرف بھیجا۔۔۔ باقی واقعہ پچھلی روایت جیسا ہے۔","",{"k":"518 نمبر کے تحت تخریج گزر چکی ہے۔"}],[525,"یعقوب بن حمید از ابراہیم از صالح از ابن شہاب از عبید اللہ کی سند سے مروی ہے کہ ابن عباس رضی اللہ عنہ نے فرمایا: ’’رسول اللہ صلی اللہ علیہ وسلم نےکسریٰ کو ایک خط بھیجا۔‘‘ بقیہ الفاظ پچھلی روایت والے ہیں۔"],[526,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’ابن شہاب کے بھتیجے نے بھی یہ روایت اسی طرح بیان کی ہے۔‘‘","",{"k":"سنن النسائي الکبری: 8845/1۔ مسند أحمد: 1/262۔ صحیح البخاري (2936) میں بھی مختصراً یہ روایت موجود ہے۔"}],[527,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’اگر کوئی معترض بطور اعتراض کہے کہ ایک روایت میں ہے: ’’بلاشبہ کلام اللہ کو تمام کلاموں پر ایسے ہی فضیلت حاصل ہے جیسے اللہ تعالیٰ کو اس کی مخلوق پر۔‘‘","",{"k":"السنۃ لعبد اللہ بن أحمد: 129۔ الرد علی الجھمیۃ للدارمي: 287۔ شرح السنۃ للالکائي: 2/339۔ یہ روایت مرفوعاً درست نہیں ہے۔ دراصل یہ ابو عبد الرحمن سلمی کا قول ہے جیسا کہ 96 نمبر کے تحت گزر چکا ہے۔ اس کی تخریج بھی وہاں موجود ہے۔"}],[528,"تو اس معترض کو جواباً کہا جائے گا کہ اگر یہ روایت صحیح ہے تو اس میں اس کےلیے کوئی دلیل موجود نہیں ہے، کیونکہ روایت کے الفاظ ہیں: ’’کلام اللہ‘‘ نہ کہ ’’مؤمنین ومنافقین اور اہل کتاب کا قول جو بسم اللہ الرحمن الرحیم پڑھتے ہیں۔‘‘ ادنیٰ شعور رکھنے والے کے نزدیک بھی یہ بات بالکل واضح ہے کہ قراءت اور مقروء (وہ کلام جسے پڑھا جاتا ہے) میں فرق ہوتا ہے۔"],[529,"فاجروں وغیرہ کے کلام کو دوسروں کے کلام پر ایسی کوئی فضیلت حاصل نہیں ہوتی جیسے خالق کو مخلوق پر فضیلت حاصل ہے۔ ہمارا رب تبارک وتعالیٰ مخلوق کی صفت سے بلند وبالا ہے۔"],[530,"اگر کوئی کہنے والا کہے کہ نبی کریم صلی اللہ علیہ وسلم سے مروی ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’یقیناً تم اللہ کی طرف رجوع کرنے کےلیے اسی سے نکلی ہوئی چیز سے افضل چیز نہیں پاسکتے۔‘‘","",{"k":"المراسیل لأبي داود: 538۔ سنن الترمذي (2912)۔ الزھد لأحمد، ص: 46۔ مرسل ہونے کی وجہ سے ضعیف ہے۔"}]])